        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{exists:true;type:function;same:true;star-same:true;plain:plain;unquoted:already-unquoted;space:space value;escaped-space:foo bar;list-splat:list value;map-splat:map value;interpolated:item-2;ordered:ordered value;trace:12;result-type:string;inspected:inspect value}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:string" as text
        \\$unquote: m.get-function("unquote", $module: "text")
        \\.sass
        \\  type: m.type-of($unquote)
