        \\@use "sass:string";
        \\$global: meta.get-function("unquote");
        \\$module: meta.get-function("unquote", $module: "string");
        \\.legacy {
        \\  exists: meta.function-exists("unquote");
        \\  module-exists: meta.function-exists("unquote", "string");
        \\  distinct: $global == $module;
        \\  inspect: meta.inspect($global);
        \\  module-inspect: meta.inspect($module);
        \\  value: meta.call($global, "legacy value");
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
