test "native Sass meta call rejects invalid string unquote arguments and limits" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "meta.call($unquote)" },
        .{ .name = "extra", .invocation = "meta.call($unquote, \"a\", \"b\")" },
        .{ .name = "unknown", .invocation = "meta.call($unquote, $string: \"a\", $other: \"b\")" },
        .{ .name = "duplicate", .invocation = "meta.call($unquote, \"a\", $string: \"b\")" },
        .{ .name = "empty-splat", .invocation = "meta.call($unquote, ()...)" },
        .{ .name = "null", .invocation = "meta.call($unquote, null)" },
        .{ .name = "boolean", .invocation = "meta.call($unquote, true)" },
        .{ .name = "number", .invocation = "meta.call($unquote, 1px)" },
        .{ .name = "list", .invocation = "meta.call($unquote, (a, b))" },
        .{ .name = "map", .invocation = "meta.call($unquote, (a: b))" },
        .{ .name = "color", .invocation = "meta.call($unquote, red)" },
        .{ .name = "calculation", .invocation = "meta.call($unquote, calc(1px + var(--x)))" },
    };
    for (invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:meta\"; @use \"sass:string\"; $unquote: meta.get-function(\"unquote\", $module: \"string\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.GeneratedCssRejected,
        compile(
            std.testing.allocator,
            "meta-call-string-unquote-invalid-css.scss",
            "@use \"sass:meta\"; @use \"sass:string\"; $unquote: meta.get-function(\"unquote\", $module: \"string\"); .a { value: meta.call($unquote, \"foo\\\"bar\"); }",
            .scss,
            .{},
        ),
    );

    var temporary = sass_evaluator.Limits{};
    temporary.max_temporary_bytes = 8;
    try std.testing.expectError(
        error.TemporaryLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-unquote-temporary-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\"; $unquote: meta.get-function(\"unquote\", $module: \"string\"); .a { value: meta.call($unquote, \"long value\"); }",
            .scss,
            temporary,
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-unquote-argument-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\" as *; $unquote: meta.get-function(\"unquote\"); .a { value: meta.call($unquote, \"value\"); }",
            .scss,
            argument_limits,
        ),
    );

    const direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "direct-empty-splat", .invocation = "string.unquote(()...)" },
        .{ .name = "direct-extra-list-splat", .invocation = "string.unquote((\"a\", \"b\")...)" },
        .{ .name = "direct-unknown-map-splat", .invocation = "string.unquote((string: \"a\", other: \"b\")...)" },
        .{ .name = "direct-invalid-map-key-splat", .invocation = "string.unquote((1: \"a\")...)" },
        .{ .name = "direct-positional-map-duplicate", .invocation = "string.unquote(\"a\", (string: \"b\")...)" },
    };
    for (direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:string\"; .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    const legacy_direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "legacy-direct-empty-splat", .invocation = "unquote(()...)" },
        .{ .name = "legacy-direct-extra-list-splat", .invocation = "unquote((\"a\", \"b\")...)" },
        .{ .name = "legacy-direct-unknown-map-splat", .invocation = "unquote((string: \"a\", other: \"b\")...)" },
        .{ .name = "legacy-direct-invalid-map-key-splat", .invocation = "unquote((1: \"a\")...)" },
    };
    for (legacy_direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            ".a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    var direct_argument_limits = sass_evaluator.Limits{};
    direct_argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "string-unquote-direct-splat-argument-limit.scss",
            "@use \"sass:string\"; .a { value: string.unquote((VALUE, OTHER)...); }",
            .scss,
            direct_argument_limits,
        ),
    );
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "legacy-string-unquote-direct-splat-argument-limit.scss",
            ".a { value: unquote((VALUE, OTHER)...); }",
            .scss,
            direct_argument_limits,
        ),
    );
}

test "native Sass meta call invokes string length function references" {
    const input =
        \\@use "sass:meta";
