        \\  @return $value;
        \\}
        \\$custom: meta.get-function("length", $module: "text");
        \\$default: meta.get-function("length", $module: "string");
        \\$star: meta.get-function("length");
        \\$list-args: ("a💚b",);
        \\$map-args: (string: "é");
        \\.values {
        \\  exists: meta.function-exists("length", "string");
