        \\  star-same: $star == $default;
        \\  ascii: meta.call($custom, plain);
        \\  quoted-unicode: meta.call($default, "a💚b");
        \\  combining: meta.call($default, "é");
        \\  zwj: meta.call($default, "👩‍💻");
