        \\  list: text.index((mark(1, "a💚b"), mark(2, "💚"))...)
        \\  map: text.index((string: mark(3, "éx"), substring: mark(4, "x"))...)
        \\  direct-map: text.index(mark(5, "abc"), (substring: mark(6, "b"))...)
        \\  override: text.index($string: "wrong", $substring: "x", (string: "axb")...)
        \\  trace: $trace
    ;
