test "native Sass meta call preserves string slice ownership" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:string";
        \\$global: meta.get-function("str-slice");
        \\$module: meta.get-function("slice", $module: "string");
        \\.legacy {
        \\  exists: meta.function-exists("str-slice");
        \\  module-exists: meta.function-exists("slice", "string");
        \\  distinct: $global == $module;
        \\  inspect: meta.inspect($global);
        \\  module-inspect: meta.inspect($module);
        \\  value: meta.call($global, "a💚b", 2, 2);
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-string-slice-ownership.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".legacy{exists:true;module-exists:true;distinct:false;inspect:get-function(\"str-slice\");module-inspect:get-function(\"slice\");value:\"💚\"}",
        result.css(),
    );
    const diagnostics = result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 1), diagnostics.len);
    try std.testing.expectEqual(
        preprocessor.diagnostics.Severity.warning,
        diagnostics[0].severity,
    );
    try std.testing.expectEqual(
        preprocessor.diagnostics.Code.invalid_operation,
        diagnostics[0].code,
    );
    try std.testing.expectEqualStrings(
        "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        diagnostics[0].message,
    );
}

test "native Sass meta call rejects invalid string slice arguments and limits" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "meta.call($slice, a)" },
        .{ .name = "extra", .invocation = "meta.call($slice, a, 1, 2, 3)" },
        .{ .name = "unknown", .invocation = "meta.call($slice, $string: a, $start-at: 1, $other: 2)" },
        .{ .name = "duplicate", .invocation = "meta.call($slice, a, 1, $string: b)" },
        .{ .name = "empty-splat", .invocation = "meta.call($slice, ()...)" },
        .{ .name = "null-string", .invocation = "meta.call($slice, null, 1)" },
        .{ .name = "boolean", .invocation = "meta.call($slice, true, 1)" },
        .{ .name = "number", .invocation = "meta.call($slice, 1px, 1)" },
        .{ .name = "list", .invocation = "meta.call($slice, (a, b), 1)" },
        .{ .name = "map", .invocation = "meta.call($slice, (a: b), 1)" },
        .{ .name = "color", .invocation = "meta.call($slice, red, 1)" },
        .{ .name = "null-start", .invocation = "meta.call($slice, abc, null)" },
        .{ .name = "null-end", .invocation = "meta.call($slice, abc, 1, null)" },
        .{ .name = "fraction", .invocation = "meta.call($slice, abc, 1.2)" },
        .{ .name = "unit", .invocation = "meta.call($slice, abc, 1px)" },
        .{ .name = "string-calculation", .invocation = "meta.call($slice, calc(1px + var(--x)), 1)" },
        .{ .name = "start-calculation", .invocation = "meta.call($slice, abc, calc(1 + var(--x)))" },
        .{ .name = "end-calculation", .invocation = "meta.call($slice, abc, 1, calc(1 + var(--x)))" },
    };
    for (invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:meta\"; @use \"sass:string\"; $slice: meta.get-function(\"slice\", $module: \"string\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    var temporary = sass_evaluator.Limits{};
    temporary.max_temporary_bytes = 8;
    try std.testing.expectError(
        error.TemporaryLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-slice-temporary-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\"; $slice: meta.get-function(\"slice\", $module: \"string\"); .a { value: meta.call($slice, \"long value\", 1); }",
            .scss,
            temporary,
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 3;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-slice-argument-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\" as *; $slice: meta.get-function(\"slice\"); .a { value: meta.call($slice, value, 1, 3); }",
            .scss,
            argument_limits,
        ),
    );

    const direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "direct-empty-splat", .invocation = "string.slice(()...)" },
        .{ .name = "direct-short-list-splat", .invocation = "string.slice((abc,)...)" },
        .{ .name = "direct-extra-list-splat", .invocation = "string.slice((abc, 1, 2, 3)...)" },
        .{ .name = "direct-unknown-map-splat", .invocation = "string.slice((string: abc, start-at: 1, other: 2)...)" },
        .{ .name = "direct-invalid-map-key-splat", .invocation = "string.slice((1: abc, start-at: 1)...)" },
        .{ .name = "direct-positional-string-map-duplicate", .invocation = "string.slice(abc, (string: def, start-at: 1)...)" },
        .{ .name = "direct-positional-start-map-duplicate", .invocation = "string.slice(abc, 1, (start-at: 2)...)" },
        .{ .name = "direct-positional-end-map-duplicate", .invocation = "string.slice(abc, 1, 2, (end-at: 3)...)" },
    };
    for (direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:string\"; .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    const legacy_direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "legacy-direct-empty-splat", .invocation = "str-slice(()...)" },
        .{ .name = "legacy-direct-short-list-splat", .invocation = "str-slice((abc,)...)" },
        .{ .name = "legacy-direct-extra-list-splat", .invocation = "str-slice((abc, 1, 2, 3)...)" },
        .{ .name = "legacy-direct-unknown-map-splat", .invocation = "str-slice((string: abc, start-at: 1, other: 2)...)" },
        .{ .name = "legacy-direct-invalid-map-key-splat", .invocation = "str-slice((1: abc, start-at: 1)...)" },
        .{ .name = "legacy-direct-positional-string-map-duplicate", .invocation = "str-slice(abc, (string: def, start-at: 1)...)" },
        .{ .name = "legacy-direct-positional-start-map-duplicate", .invocation = "str-slice(abc, 1, (start-at: 2)...)" },
        .{ .name = "legacy-direct-positional-end-map-duplicate", .invocation = "str-slice(abc, 1, 2, (end-at: 3)...)" },
    };
    for (legacy_direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            ".a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    var direct_argument_limits = sass_evaluator.Limits{};
    direct_argument_limits.max_function_arguments = 3;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "string-slice-direct-splat-argument-limit.scss",
            "@use \"sass:string\"; .a { value: string.slice((value, 1, 2, other)...); }",
            .scss,
            direct_argument_limits,
        ),
    );
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "legacy-string-slice-direct-splat-argument-limit.scss",
            ".a { value: str-slice((value, 1, 2, other)...); }",
            .scss,
            direct_argument_limits,
        ),
    );
}

test "native Sass meta call invokes string insert function references" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:string";
        \\@use "sass:string" as text;
        \\@use "sass:string" as *;
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$custom: meta.get-function("insert", $module: "text");
        \\$default: meta.get-function("insert", $module: "string");
        \\$star: meta.get-function("insert");
        \\$list-args: ("a💚b", "🌍", 2);
        \\$map-args: (string: "éx", insert: "*", index: 2);
        \\.values {
        \\  exists: meta.function-exists("insert", "string");
        \\  type: meta.type-of($default);
        \\  same: $custom == $default;
        \\  star-same: $star == $default;
        \\  ascii: meta.call($custom, banana, X, 2);
        \\  quoted-unicode: meta.call($default, "a💚b", "🌍", 2);
        \\  combining: meta.call($default, "éx", "*", 2);
        \\  zwj: meta.call($default, "👩‍💻", "X", 3);
        \\  quoted-hex: meta.call($default, "ac", "x\62 y", 2);
        \\  unquoted-hex: meta.call($default, ac, x\62 y, 2);
        \\  quoted-simple: meta.call($default, "ab", "x\ y", 2);
        \\  unquoted-simple: meta.call($default, ab, x\ y, 2);
        \\  negative: meta.call($default, "hello", "X", -2);
        \\  append: meta.call($default, "hello", "X", -1);
        \\  prepend: meta.call($default, "hello", "X", -20);
        \\  clamped: meta.call($default, "hello", "X", 20);
        \\  zero: meta.call($default, "hello", "X", 0);
        \\  empty: meta.call($default, "", "X", 1);
        \\  mixed-quoted: meta.call($default, "ab", x\ y, 2);
        \\  mixed-unquoted: meta.call($default, ab, "x y", 2);
        \\  list-splat: meta.call($custom, $list-args...);
        \\  map-splat: meta.call($default, $map-args...);
        \\  interpolated: meta.call($default, item-#{24}, "X", 5);
        \\  ordered: meta.call(mark(1, $star), $index: mark(2, 3), $string: mark(3, abcd), $insert: mark(4, X));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($default, "typed", "X", 2));
        \\  inspected: meta.inspect(meta.call($default, "inspect", "X", 3));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-string-insert-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{exists:true;type:function;same:true;star-same:true;ascii:bXanana;quoted-unicode:\"a🌍💚b\";combining:\"e*́x\";zwj:\"👩‍X💻\";quoted-hex:\"axbyc\";unquoted-hex:axbyc;quoted-simple:\"ax yb\";unquoted-simple:ax\\ yb;negative:\"hellXo\";append:\"helloX\";prepend:\"Xhello\";clamped:\"helloX\";zero:\"Xhello\";empty:\"X\";mixed-quoted:\"ax\\\\ yb\";mixed-unquoted:ax yb;list-splat:\"a🌍💚b\";map-splat:\"e*́x\";interpolated:itemX-24;ordered:abXcd;trace:1234;result-type:string;inspected:\"inXspect\"}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:string" as text
        \\$insert: m.get-function("insert", $module: "text")
        \\.sass
        \\  type: m.type-of($insert)
        \\  plain: m.call($insert, banana, X, 2)
        \\  named: m.call($insert, $index: 2, $string: "a💚b", $insert: "🌍")
        \\  escaped: m.call($insert, ab, x\ y, 2)
        \\  clamped: m.call($insert, hello, X, -20)
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-call-string-insert-function.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{type:function;plain:bXanana;named:\"a🌍💚b\";escaped:ax\\ yb;clamped:Xhello}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);
}

