test "native Sass meta call preserves string upper case ownership" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:string";
        \\$global: meta.get-function("to-upper-case");
        \\$module: meta.get-function("to-upper-case", $module: "string");
        \\.legacy {
        \\  exists: meta.function-exists("to-upper-case");
        \\  module-exists: meta.function-exists("to-upper-case", "string");
        \\  distinct: $global == $module;
        \\  inspect: meta.inspect($global);
        \\  module-inspect: meta.inspect($module);
        \\  value: meta.call($global, "a💚éßıiẞb");
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-string-upper-case-ownership.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".legacy{exists:true;module-exists:true;distinct:false;inspect:get-function(\"to-upper-case\");module-inspect:get-function(\"to-upper-case\");value:\"A💚éßıIẞB\"}",
        result.css(),
    );
    const diagnostics = result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 1), diagnostics.len);
    try std.testing.expectEqual(
        preprocessor.diagnostics.Severity.warning,
        diagnostics[0].severity,
    );
    try std.testing.expectEqual(
        preprocessor.diagnostics.Code.invalid_operation,
        diagnostics[0].code,
    );
    try std.testing.expectEqualStrings(
        "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        diagnostics[0].message,
    );
}

test "native Sass meta call rejects invalid string upper case arguments and limits" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "meta.call($upper)" },
        .{ .name = "extra", .invocation = "meta.call($upper, a, b)" },
        .{ .name = "unknown", .invocation = "meta.call($upper, $string: a, $other: b)" },
        .{ .name = "duplicate", .invocation = "meta.call($upper, a, $string: b)" },
        .{ .name = "empty-splat", .invocation = "meta.call($upper, ()...)" },
        .{ .name = "null", .invocation = "meta.call($upper, null)" },
        .{ .name = "boolean", .invocation = "meta.call($upper, true)" },
        .{ .name = "number", .invocation = "meta.call($upper, 1px)" },
        .{ .name = "list", .invocation = "meta.call($upper, (a, b))" },
        .{ .name = "map", .invocation = "meta.call($upper, (a: b))" },
        .{ .name = "color", .invocation = "meta.call($upper, red)" },
        .{ .name = "calculation", .invocation = "meta.call($upper, calc(1px + var(--x)))" },
    };
    for (invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:meta\"; @use \"sass:string\"; $upper: meta.get-function(\"to-upper-case\", $module: \"string\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    var temporary = sass_evaluator.Limits{};
    temporary.max_temporary_bytes = 8;
    try std.testing.expectError(
        error.TemporaryLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-upper-case-temporary-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\"; $upper: meta.get-function(\"to-upper-case\", $module: \"string\"); .a { value: meta.call($upper, \"long value\"); }",
            .scss,
            temporary,
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-upper-case-argument-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\" as *; $upper: meta.get-function(\"to-upper-case\"); .a { value: meta.call($upper, value); }",
            .scss,
            argument_limits,
        ),
    );

    const direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "direct-empty-splat", .invocation = "string.to-upper-case(()...)" },
        .{ .name = "direct-extra-list-splat", .invocation = "string.to-upper-case((a, b)...)" },
        .{ .name = "direct-unknown-map-splat", .invocation = "string.to-upper-case((string: a, other: b)...)" },
        .{ .name = "direct-invalid-map-key-splat", .invocation = "string.to-upper-case((1: a)...)" },
        .{ .name = "direct-positional-map-duplicate", .invocation = "string.to-upper-case(a, (string: b)...)" },
    };
    for (direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:string\"; .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    const legacy_direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "legacy-direct-empty-splat", .invocation = "to-upper-case(()...)" },
        .{ .name = "legacy-direct-extra-list-splat", .invocation = "to-upper-case((a, b)...)" },
        .{ .name = "legacy-direct-unknown-map-splat", .invocation = "to-upper-case((string: a, other: b)...)" },
        .{ .name = "legacy-direct-invalid-map-key-splat", .invocation = "to-upper-case((1: a)...)" },
        .{ .name = "legacy-direct-positional-map-duplicate", .invocation = "to-upper-case(a, (string: b)...)" },
    };
    for (legacy_direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            ".a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    var direct_argument_limits = sass_evaluator.Limits{};
    direct_argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "string-upper-case-direct-splat-argument-limit.scss",
            "@use \"sass:string\"; .a { value: string.to-upper-case((value, other)...); }",
            .scss,
            direct_argument_limits,
        ),
    );
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "legacy-string-upper-case-direct-splat-argument-limit.scss",
            ".a { value: to-upper-case((VALUE, OTHER)...); }",
            .scss,
            direct_argument_limits,
        ),
    );
}

test "native Sass expands direct string module lower case arguments once in source order" {
    const input =
        \\@use "sass:string";
        \\@use "sass:string" as text;
        \\@use "sass:string" as *;
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\.values {
        \\  list: string.to-lower-case((mark(1, "A💚É"),)...);
        \\  map: text.to-lower-case((string: mark(2, "ÉX"))...);
        \\  star: to-lower-case((string: mark(3, "A👩‍💻Z"))...);
        \\  override: string.to-lower-case($string: "wrong", (string: mark(4, "ABCÉ"))...);
        \\  trace: $trace;
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "string-lower-case-direct-splat.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{list:\"a💚É\";map:\"éx\";star:\"a👩‍💻z\";override:\"abcÉ\";trace:1234}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:string" as text
        \\$trace: 0
        \\@function mark($digit, $value)
        \\  $trace: $trace * 10 + $digit !global
        \\  @return $value
        \\.sass
        \\  list: text.to-lower-case((mark(1, "A💚É"),)...)
        \\  map: text.to-lower-case((string: mark(2, "ÉX"))...)
        \\  override: text.to-lower-case($string: "wrong", (string: mark(3, "ABCÉ"))...)
        \\  trace: $trace
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "string-lower-case-direct-splat.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{list:\"a💚É\";map:\"éx\";override:\"abcÉ\";trace:123}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseDirectStringLowerCaseSplatAllocationFailures,
        .{},
    );
}

