        ".legacy{exists:true;module-exists:true;distinct:false;inspect:get-function(\"to-lower-case\");module-inspect:get-function(\"to-lower-case\");value:\"a💚Éẞiİb\"}",
        result.css(),
    );
    const diagnostics = result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 1), diagnostics.len);
    try std.testing.expectEqual(
        preprocessor.diagnostics.Severity.warning,
        diagnostics[0].severity,
    );
    try std.testing.expectEqual(
        preprocessor.diagnostics.Code.invalid_operation,
        diagnostics[0].code,
    );
    try std.testing.expectEqualStrings(
        "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        diagnostics[0].message,
    );
}

test "native Sass meta call rejects invalid string lower case arguments and limits" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "meta.call($lower)" },
        .{ .name = "extra", .invocation = "meta.call($lower, A, B)" },
        .{ .name = "unknown", .invocation = "meta.call($lower, $string: A, $other: B)" },
        .{ .name = "duplicate", .invocation = "meta.call($lower, A, $string: B)" },
        .{ .name = "empty-splat", .invocation = "meta.call($lower, ()...)" },
        .{ .name = "null", .invocation = "meta.call($lower, null)" },
        .{ .name = "boolean", .invocation = "meta.call($lower, true)" },
        .{ .name = "number", .invocation = "meta.call($lower, 1px)" },
        .{ .name = "list", .invocation = "meta.call($lower, (A, B))" },
        .{ .name = "map", .invocation = "meta.call($lower, (A: B))" },
        .{ .name = "color", .invocation = "meta.call($lower, red)" },
        .{ .name = "calculation", .invocation = "meta.call($lower, calc(1px + var(--x)))" },
    };
    for (invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:meta\"; @use \"sass:string\"; $lower: meta.get-function(\"to-lower-case\", $module: \"string\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    var temporary = sass_evaluator.Limits{};
    temporary.max_temporary_bytes = 8;
    try std.testing.expectError(
        error.TemporaryLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-lower-case-temporary-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\"; $lower: meta.get-function(\"to-lower-case\", $module: \"string\"); .a { value: meta.call($lower, \"LONG VALUE\"); }",
            .scss,
            temporary,
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-lower-case-argument-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\" as *; $lower: meta.get-function(\"to-lower-case\"); .a { value: meta.call($lower, VALUE); }",
            .scss,
            argument_limits,
        ),
    );

    const direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "direct-empty-splat", .invocation = "string.to-lower-case(()...)" },
        .{ .name = "direct-extra-list-splat", .invocation = "string.to-lower-case((A, B)...)" },
        .{ .name = "direct-unknown-map-splat", .invocation = "string.to-lower-case((string: A, other: B)...)" },
        .{ .name = "direct-invalid-map-key-splat", .invocation = "string.to-lower-case((1: A)...)" },
        .{ .name = "direct-positional-map-duplicate", .invocation = "string.to-lower-case(A, (string: B)...)" },
    };
    for (direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:string\"; .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    const legacy_direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "legacy-direct-empty-splat", .invocation = "to-lower-case(()...)" },
        .{ .name = "legacy-direct-extra-list-splat", .invocation = "to-lower-case((A, B)...)" },
        .{ .name = "legacy-direct-unknown-map-splat", .invocation = "to-lower-case((string: A, other: B)...)" },
        .{ .name = "legacy-direct-invalid-map-key-splat", .invocation = "to-lower-case((1: A)...)" },
        .{ .name = "legacy-direct-positional-map-duplicate", .invocation = "to-lower-case(A, (string: B)...)" },
    };
    for (legacy_direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            ".a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    var direct_argument_limits = sass_evaluator.Limits{};
    direct_argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "string-lower-case-direct-splat-argument-limit.scss",
            "@use \"sass:string\"; .a { value: string.to-lower-case((VALUE, OTHER)...); }",
            .scss,
            direct_argument_limits,
        ),
    );
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "legacy-string-lower-case-direct-splat-argument-limit.scss",
            ".a { value: to-lower-case((VALUE, OTHER)...); }",
            .scss,
            direct_argument_limits,
        ),
    );
}

test "native Sass invokes direct and reflected string split functions" {
    const input =
        \\@use "sass:list";
        \\@use "sass:meta";
        \\@use "sass:string";
        \\@use "sass:string" as text;
        \\@use "sass:string" as *;
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$custom: meta.get-function("split", $module: "text");
        \\$default: meta.get-function("split", $module: "string");
        \\$star: meta.get-function("split");
        \\$list-args: ("a-b-c", "-", 1);
        \\$map-args: (string: "a💚b💚c", separator: "💚", limit: 1);
        \\$parts: meta.call($default, "a-b-c", "-");
        \\.values {
        \\  exists: meta.function-exists("split", "string");
        \\  type: meta.type-of($default);
        \\  same: $custom == $default;
        \\  star-same: $star == $default;
        \\  direct: meta.inspect(string.split("a-b-c", "-"));
        \\  quoted: meta.inspect(meta.call($default, "a-b-c", "-"));
        \\  unquoted: meta.inspect(meta.call($default, foo-bar-baz, "-"));
        \\  unicode: meta.inspect(meta.call($default, "a💚b💚c", "💚"));
        \\  combining: meta.inspect(meta.call($default, "éx́y", "́"));
        \\  zwj: meta.inspect(meta.call($default, "👩‍💻", "‍"));
        \\  escaped: meta.inspect(meta.call($default, "a\62 c", "b"));
        \\  unquoted-escaped: meta.inspect(meta.call($default, a\62 c, b));
        \\  multi: meta.inspect(meta.call($default, "aaaaa", "aa"));
        \\  absent: meta.inspect(meta.call($default, "abc", "x"));
        \\  empties: meta.inspect(meta.call($default, "-a--b-", "-"));
        \\  empty-string: meta.inspect(meta.call($default, "", "-"));
        \\  empty-separator: meta.inspect(meta.call($default, "a💚b", ""));
        \\  limit-one: meta.inspect(meta.call($default, "a-b-c", "-", 1));
        \\  limit-two: meta.inspect(meta.call($default, "a-b-c-d", "-", 2));
        \\  limit-null: meta.inspect(meta.call($default, "a-b-c", "-", null));
        \\  unit-limit: meta.inspect(meta.call($default, "a-b-c", "-", 1px));
        \\  fuzzy-limit: meta.inspect(meta.call($default, "a-b-c", "-", 1.000000000001));
        \\  list-splat: meta.inspect(meta.call($custom, $list-args...));
        \\  map-splat: meta.inspect(meta.call($default, $map-args...));
        \\  bracketed: list.is-bracketed($parts);
        \\  separator: list.separator($parts);
        \\  length: list.length($parts);
        \\  item-type: meta.type-of(list.nth($parts, 1));
        \\  ordered: meta.inspect(meta.call(mark(1, $star), $limit: mark(2, 1), $string: mark(3, "a-b-c"), $separator: mark(4, "-")));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($default, "a-b", "-"));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-string-split-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{exists:true;type:function;same:true;star-same:true;direct:[\"a\", \"b\", \"c\"];quoted:[\"a\", \"b\", \"c\"];unquoted:[foo, bar, baz];unicode:[\"a\", \"b\", \"c\"];combining:[\"e\", \"x\", \"y\"];zwj:[\"👩\", \"💻\"];escaped:[\"a\", \"c\"];unquoted-escaped:[a, c];multi:[\"\", \"\", \"a\"];absent:[\"abc\",];empties:[\"\", \"a\", \"\", \"b\", \"\"];empty-string:[];empty-separator:[\"a\", \"💚\", \"b\"];limit-one:[\"a\", \"b-c\"];limit-two:[\"a\", \"b\", \"c-d\"];limit-null:[\"a\", \"b\", \"c\"];unit-limit:[\"a\", \"b-c\"];fuzzy-limit:[\"a\", \"b-c\"];list-splat:[\"a\", \"b-c\"];map-splat:[\"a\", \"b💚c\"];bracketed:true;separator:comma;length:3;item-type:string;ordered:[\"a\", \"b-c\"];trace:1234;result-type:list}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:string" as text
        \\$split: m.get-function("split", $module: "text")
        \\.sass
        \\  type: m.type-of($split)
        \\  plain: m.inspect(m.call($split, "a-b-c", "-"))
        \\  named: m.inspect(m.call($split, $limit: 1, $separator: "💚", $string: "a💚b💚c"))
        \\  direct: m.inspect(text.split("a--b", "--"))
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-call-string-split-function.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{type:function;plain:[\"a\", \"b\", \"c\"];named:[\"a\", \"b💚c\"];direct:[\"a\", \"b\"]}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);
}

test "native Sass expands direct string split arguments once in source order" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:string";
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\.values {
        \\  list: meta.inspect(string.split((mark(1, "a-b-c"), mark(2, "-"), mark(3, 1))...));
        \\  map: meta.inspect(string.split((string: mark(4, "a-b-c"), separator: mark(5, "-"), limit: mark(6, 1))...));
        \\  mixed: meta.inspect(string.split(mark(7, "a-b-c"), (separator: mark(8, "-"), limit: mark(9, 1))...));
        \\  override: meta.inspect(string.split($string: mark(1, "wrong"), (string: mark(2, "a-b-c"), separator: mark(3, "-"), limit: mark(4, 1))...));
        \\  trace: $trace;
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "string-split-direct-splat.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{list:[\"a\", \"b-c\"];map:[\"a\", \"b-c\"];mixed:[\"a\", \"b-c\"];override:[\"a\", \"b-c\"];trace:1234567891234}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:string" as text
        \\$trace: 0
        \\@function mark($digit, $value)
        \\  $trace: $trace * 10 + $digit !global
        \\  @return $value
        \\.sass
        \\  list: m.inspect(text.split((mark(1, "a-b-c"), mark(2, "-"), mark(3, 1))...))
        \\  map: m.inspect(text.split((string: mark(4, "a-b-c"), separator: mark(5, "-"), limit: mark(6, 1))...))
        \\  mixed: m.inspect(text.split(mark(7, "a-b-c"), (separator: mark(8, "-"), limit: mark(9, 1))...))
        \\  trace: $trace
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "string-split-direct-splat.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{list:[\"a\", \"b-c\"];map:[\"a\", \"b-c\"];mixed:[\"a\", \"b-c\"];trace:123456789}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);
}

test "native Sass string split preserves the closed global boundary" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:string";
        \\.boundary {
        \\  exists: meta.function-exists("split");
        \\  module-exists: meta.function-exists("split", "string");
        \\  bare: split("a-b", "-");
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "string-split-global-boundary.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".boundary{exists:false;module-exists:true;bare:split(\"a-b\", \"-\")}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);
}

test "native Sass string split rejects invalid arguments and limits" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "meta.call($split, a)" },
        .{ .name = "extra", .invocation = "meta.call($split, a, b, 1, 2)" },
        .{ .name = "unknown", .invocation = "meta.call($split, $string: a, $separator: b, $other: 1)" },
        .{ .name = "duplicate", .invocation = "meta.call($split, a, b, $string: c)" },
        .{ .name = "empty-splat", .invocation = "meta.call($split, ()...)" },
        .{ .name = "null-string", .invocation = "meta.call($split, null, b)" },
        .{ .name = "boolean-string", .invocation = "meta.call($split, true, b)" },
        .{ .name = "number-string", .invocation = "meta.call($split, 1, b)" },
        .{ .name = "list-string", .invocation = "meta.call($split, (a, b), b)" },
        .{ .name = "map-string", .invocation = "meta.call($split, (a: b), b)" },
        .{ .name = "color-string", .invocation = "meta.call($split, red, b)" },
        .{ .name = "calculation-string", .invocation = "meta.call($split, calc(1px + var(--x)), b)" },
        .{ .name = "null-separator", .invocation = "meta.call($split, a, null)" },
        .{ .name = "number-separator", .invocation = "meta.call($split, a, 1)" },
        .{ .name = "color-separator", .invocation = "meta.call($split, red, red)" },
        .{ .name = "calculation-separator", .invocation = "meta.call($split, a, calc(1 + var(--x)))" },
        .{ .name = "boolean-limit", .invocation = "meta.call($split, a, b, true)" },
        .{ .name = "string-limit", .invocation = "meta.call($split, a, b, one)" },
        .{ .name = "calculation-limit", .invocation = "meta.call($split, a, b, calc(1 + var(--x)))" },
        .{ .name = "fraction-limit", .invocation = "meta.call($split, a, b, 1.5)" },
        .{ .name = "zero-limit", .invocation = "meta.call($split, a, b, 0)" },
        .{ .name = "negative-limit", .invocation = "meta.call($split, a, b, -1)" },
        .{ .name = "direct-empty-splat", .invocation = "string.split(()...)" },
        .{ .name = "direct-extra-list-splat", .invocation = "string.split((a, b, 1, 2)...)" },
        .{ .name = "direct-unknown-map-splat", .invocation = "string.split((string: a, separator: b, other: 1)...)" },
        .{ .name = "direct-invalid-map-key-splat", .invocation = "string.split((1: a, separator: b)...)" },
    };
    for (invalid) |case| {
        const case_source = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:meta\"; @use \"sass:string\"; $split: meta.get-function(\"split\", $module: \"string\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(case_source);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, case_source, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-string-split-module-not-loaded.scss",
            "@use \"sass:meta\"; $split: meta.get-function(\"split\", $module: \"string\"); .a { value: meta.call($split, a, b); }",
            .scss,
            .{},
        ),
    );

    var temporary = sass_evaluator.Limits{};
    temporary.max_temporary_bytes = 48;
    try std.testing.expectError(
        error.TemporaryLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-split-temporary-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\"; $split: meta.get-function(\"split\", $module: \"string\"); .a { value: meta.call($split, \"a-b-c-d-e-f\", \"-\"); }",
            .scss,
            temporary,
        ),
    );

    var collections = sass_evaluator.Limits{};
    collections.values.max_collection_items = 2;
    try std.testing.expectError(
        error.ValueLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-split-collection-limit.scss",
            "@use \"sass:string\"; .a { value: string.split(\"a-b-c\", \"-\"); }",
            .scss,
            collections,
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 3;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-string-split-argument-limit.scss",
            "@use \"sass:meta\"; @use \"sass:string\" as *; $split: meta.get-function(\"split\"); .a { value: meta.call($split, \"a-b-c\", \"-\", 1); }",
            .scss,
            argument_limits,
        ),
    );
    var direct_argument_limits = sass_evaluator.Limits{};
    direct_argument_limits.max_function_arguments = 2;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "string-split-direct-splat-argument-limit.scss",
            "@use \"sass:string\"; .a { value: string.split((\"a-b-c\", \"-\", 1)...); }",
            .scss,
            direct_argument_limits,
        ),
    );
}

test "native Sass meta call invokes color adjust function references" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:color";
        \\@use "sass:color" as palette;
        \\@use "sass:color" as *;
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$custom: meta.get-function("adjust", $module: "palette");
        \\$default: meta.get-function("adjust", $module: "color");
        \\$alias: meta.get-function("adjust", $module: "palette");
        \\$star: meta.get-function("adjust");
        \\$list-args: (#123456,);
        \\$map-args: (color: hsl(120, 40%, 50%), saturation: 10%);
        \\.values {
        \\  exists: meta.function-exists("adjust", "color");
        \\  type: meta.type-of($default);
        \\  same: $custom == $default;
        \\  alias-same: $alias == $default;
        \\  star-same: $star == $default;
        \\  rgb: meta.call($custom, #123456, $red: 10);
        \\  rgb-percent: meta.call($default, #123456, $green: 10%);
        \\  hsl: meta.call($default, hsl(120, 40%, 50%), $saturation: 10%);
        \\  hwb: meta.call($default, hwb(30 20% 30%), $whiteness: 5%);
        \\  lab: meta.call($default, lab(50% 10 20), $a: 5, $space: lab);
        \\  lch: meta.call($default, lch(50% 20 30deg), $chroma: 5, $hue: 15deg, $space: lch);
        \\  p3: meta.call($default, color(display-p3 .2 .3 .4), $red: .1, $space: display-p3);
        \\  alpha: meta.call($default, rgba(1, 2, 3, .4), $alpha: .1);
        \\  named: meta.call($default, $blue: 10, $color: #123456);
        \\  unchanged: meta.call($default, #123456);
        \\  list-splat: meta.call($custom, $blue: 10, $list-args...);
        \\  map-splat: meta.call($default, $map-args...);
        \\  ordered: meta.call(mark(1, $star), $blue: mark(2, 10), $color: mark(3, #123456));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($default, #123456, $red: 1));
        \\  inspected: meta.inspect(meta.call($default, #123456, $red: 1));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-color-adjust-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{exists:true;type:function;same:true;alias-same:true;star-same:true;rgb:#1c3456;rgb-percent:rgb(18,77.5,86);hsl:hsl(120,50%,50%);hwb:rgb(178.5,121.125,63.75);lab:lab(50 15 20);lch:lch(50 25 45);p3:color(display-p3 .3 .3 .4);alpha:rgba(1,2,3,.5);named:#123460;unchanged:#123456;list-splat:#123460;map-splat:hsl(120,50%,50%);ordered:#123460;trace:123;result-type:color;inspected:#133456}",
        result.css(),
