    const indented =
        \\@use "sass:meta" as m
        \\$lch: m.get-function("lch")
        \\$arguments: ("channels": 50% 20 30deg / .4)
        \\.sass
        \\  type: m.type-of($lch)
        \\  plain: m.call($lch, 50% 20 30deg / .4)
        \\  named: m.call($lch, $channels: 50% 20 30deg)
        \\  map: m.call($lch, $arguments...)
    ;
