test "native Sass meta call rejects unavailable blackness forms arguments and limits" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "meta.call($blackness)" },
        .{ .name = "extra", .invocation = "meta.call($blackness, red, rgb)" },
        .{ .name = "unknown", .invocation = "meta.call($blackness, $other: red)" },
        .{ .name = "duplicate", .invocation = "meta.call($blackness, red, $color: blue)" },
        .{ .name = "empty-splat", .invocation = "meta.call($blackness, ()...)" },
        .{ .name = "null", .invocation = "meta.call($blackness, null)" },
        .{ .name = "boolean", .invocation = "meta.call($blackness, true)" },
        .{ .name = "number", .invocation = "meta.call($blackness, 1)" },
        .{ .name = "quoted", .invocation = "meta.call($blackness, \"blackness\")" },
        .{ .name = "unquoted", .invocation = "meta.call($blackness, blackness)" },
        .{ .name = "list", .invocation = "meta.call($blackness, (red, blue))" },
        .{ .name = "map", .invocation = "meta.call($blackness, (a: red))" },
        .{ .name = "callable", .invocation = "meta.call($blackness, meta.get-function(\"inspect\", $module: \"meta\"))" },
        .{ .name = "space", .invocation = "meta.call($blackness, red, $space: hwb)" },
        .{ .name = "lab", .invocation = "meta.call($blackness, lab(50% 10 20))" },
        .{ .name = "lch", .invocation = "meta.call($blackness, lch(50% 20 30deg))" },
        .{ .name = "oklab", .invocation = "meta.call($blackness, oklab(50% .1 .2))" },
        .{ .name = "oklch", .invocation = "meta.call($blackness, oklch(50% .1 30deg))" },
        .{ .name = "srgb", .invocation = "meta.call($blackness, color(srgb .1 .2 .3))" },
        .{ .name = "srgb-linear", .invocation = "meta.call($blackness, color(srgb-linear .1 .2 .3))" },
        .{ .name = "display-p3", .invocation = "meta.call($blackness, color(display-p3 .1 .2 .3))" },
        .{ .name = "a98-rgb", .invocation = "meta.call($blackness, color(a98-rgb .1 .2 .3))" },
        .{ .name = "prophoto-rgb", .invocation = "meta.call($blackness, color(prophoto-rgb .1 .2 .3))" },
        .{ .name = "rec2020", .invocation = "meta.call($blackness, color(rec2020 .1 .2 .3))" },
        .{ .name = "xyz-d50", .invocation = "meta.call($blackness, color(xyz-d50 .1 .2 .3))" },
        .{ .name = "xyz-d65", .invocation = "meta.call($blackness, color(xyz-d65 .1 .2 .3))" },
        .{ .name = "variable", .invocation = "meta.call($blackness, var(--color))" },
        .{ .name = "calculation", .invocation = "meta.call($blackness, calc(1 + var(--x)))" },
    };
    for (invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:meta\"; @use \"sass:color\"; $blackness: meta.get-function(\"blackness\", $module: \"color\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-blackness-global.scss",
            "@use \"sass:meta\"; @use \"sass:color\"; $blackness: meta.get-function(\"blackness\"); .a { value: meta.call($blackness, red); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-blackness-module-not-loaded.scss",
            "@use \"sass:meta\"; .a { value: meta.call(meta.get-function(\"blackness\", $module: \"color\"), red); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-blackness-module-member.scss",
            "@use \"sass:meta\"; @use \"sass:color\"; .a { value: meta.call(meta.get-function(\"tone\", $module: \"color\"), red); }",
            .scss,
            .{},
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-blackness-argument-limit.scss",
            "@use \"sass:meta\"; @use \"sass:color\"; $blackness: meta.get-function(\"blackness\", $module: \"color\"); .a { value: meta.call($blackness, red); }",
            .scss,
            argument_limits,
        ),
    );

    const direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "direct-empty-splat", .invocation = "color.blackness(()...)" },
        .{ .name = "direct-overfull-list-splat", .invocation = "color.blackness((red, blue)...)" },
        .{ .name = "direct-unknown-map-splat", .invocation = "color.blackness((color: red, other: blue)...)" },
        .{ .name = "direct-invalid-map-key-splat", .invocation = "color.blackness((1: red)...)" },
        .{ .name = "direct-positional-map-duplicate", .invocation = "color.blackness(red, (color: blue)...)" },
        .{ .name = "direct-modern-color", .invocation = "color.blackness(color(display-p3 .3 .4 .5))" },
        .{ .name = "direct-deferred", .invocation = "color.blackness(var(--color))" },
    };
    for (direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:color\"; .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "color-blackness-direct-function-argument-limit.scss",
            "@use \"sass:color\"; .a { value: color.blackness((red, blue)...); }",
            .scss,
            argument_limits,
        ),
    );
}

test "native Sass meta call invokes legacy color mix function references" {
    const input =
        \\@use "sass:meta";
        \\$global: meta.get-function("mix");
        \\@use "sass:color";
        \\@use "sass:color" as palette;
        \\$module: meta.get-function("mix", $module: "color");
        \\$alias: meta.get-function("mix", $module: "palette");
        \\@use "sass:color" as *;
        \\$star: meta.get-function("mix");
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$list-args: (red, blue, 25%);
        \\$map-args: ("color1": red, "color2": blue, "weight": 25%);
        \\.values {
        \\  global-exists: meta.function-exists("mix");
        \\  module-exists: meta.function-exists("mix", "color");
        \\  alias-exists: meta.function-exists("mix", "palette");
        \\  type: meta.type-of($module);
        \\  global-module-same: $global == $module;
        \\  module-alias-same: $module == $alias;
        \\  star-module-same: $star == $module;
        \\  star-global-same: $star == $global;
        \\  inspect-global: meta.inspect($global);
        \\  inspect-module: meta.inspect($module);
        \\  global: meta.call($global, red, blue);
        \\  module: meta.call($module, red, blue);
        \\  named: meta.call($module, $weight: 25%, $color2: blue, $color1: red);
        \\  transparent: meta.call($module, transparent, blue);
        \\  alpha: meta.call($module, rgba(255, 0, 0, .5), blue);
        \\  hsl-hwb: meta.call($module, hsl(120deg 50% 25%), hwb(240deg 10% 20%), 25%);
        \\  list-splat: meta.call($module, $list-args...);
        \\  map-splat: meta.call($module, $map-args...);
        \\  ordered: meta.call(mark(1, $module), mark(2, red), $weight: mark(4, 25%), $color2: mark(3, blue));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($module, red, blue));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-color-mix-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{global-exists:true;module-exists:true;alias-exists:true;type:function;global-module-same:false;module-alias-same:true;star-module-same:true;star-global-same:false;inspect-global:get-function(\"mix\");inspect-module:get-function(\"mix\");global:hsl(300,100%,25%);module:hsl(300,100%,25%);named:rgb(63.75,0,191.25);transparent:rgba(0,0,255,.5);alpha:rgba(63.75,0,191.25,.75);hsl-hwb:rgb(27.09375,43.03125,160.96875);list-splat:rgb(63.75,0,191.25);map-splat:rgb(63.75,0,191.25);ordered:rgb(63.75,0,191.25);trace:1243;result-type:color}",
        result.css(),
    );
    const diagnostics = result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 1), diagnostics.len);
    try std.testing.expectEqual(
        preprocessor.diagnostics.Severity.warning,
        diagnostics[0].severity,
    );
    try std.testing.expectEqual(
        preprocessor.diagnostics.Code.invalid_operation,
        diagnostics[0].code,
    );
    try std.testing.expectEqualStrings(
        "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        diagnostics[0].message,
    );

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:color" as palette
        \\$mix: m.get-function("mix", $module: "palette")
        \\$arguments: ("color1": red, "color2": blue, "weight": 25%)
        \\.sass
        \\  type: m.type-of($mix)
        \\  plain: m.call($mix, red, blue)
        \\  named: m.call($mix, $color1: red, $color2: blue, $weight: 25%)
        \\  map: m.call($mix, $arguments...)
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-call-color-mix-function.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{type:function;plain:hsl(300,100%,25%);named:rgb(63.75,0,191.25);map:rgb(63.75,0,191.25)}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseColorMixFunctionAllocationFailures,
        .{},
    );
}

