        .{ .name = "map", .invocation = "meta.call($mix, red, (tone: blue))" },
        .{ .name = "callable", .invocation = "meta.call($mix, red, meta.get-function(\"inspect\", $module: \"meta\"))" },
        .{ .name = "unitless-weight", .invocation = "meta.call($mix, red, blue, 25)" },
        .{ .name = "unit-weight", .invocation = "meta.call($mix, red, blue, 25px)" },
        .{ .name = "negative-weight", .invocation = "meta.call($mix, red, blue, -1%)" },
        .{ .name = "high-weight", .invocation = "meta.call($mix, red, blue, 101%)" },
        .{ .name = "calculation-weight", .invocation = "meta.call($mix, red, blue, calc(25% + var(--weight)))" },
        .{ .name = "method", .invocation = "meta.call($mix, red, blue, $method: rgb)" },
        .{ .name = "rgb-missing", .invocation = "meta.call($mix, rgb(none 0 0), blue)" },
        .{ .name = "lab", .invocation = "meta.call($mix, lab(50% 10 20), lab(40% 5 10))" },
        .{ .name = "lch", .invocation = "meta.call($mix, lch(50% 20 30deg), lch(40% 10 20deg))" },
        .{ .name = "oklab", .invocation = "meta.call($mix, oklab(50% .1 .2), oklab(40% .05 .1))" },
        .{ .name = "oklch", .invocation = "meta.call($mix, oklch(50% .1 30deg), oklch(40% .05 20deg))" },
        .{ .name = "srgb", .invocation = "meta.call($mix, color(srgb .1 .2 .3), color(srgb .3 .2 .1))" },
        .{ .name = "srgb-linear", .invocation = "meta.call($mix, color(srgb-linear .1 .2 .3), color(srgb-linear .3 .2 .1))" },
        .{ .name = "display-p3", .invocation = "meta.call($mix, color(display-p3 .1 .2 .3), color(display-p3 .3 .2 .1))" },
        .{ .name = "a98-rgb", .invocation = "meta.call($mix, color(a98-rgb .1 .2 .3), color(a98-rgb .3 .2 .1))" },
        .{ .name = "prophoto-rgb", .invocation = "meta.call($mix, color(prophoto-rgb .1 .2 .3), color(prophoto-rgb .3 .2 .1))" },
        .{ .name = "rec2020", .invocation = "meta.call($mix, color(rec2020 .1 .2 .3), color(rec2020 .3 .2 .1))" },
        .{ .name = "xyz-d50", .invocation = "meta.call($mix, color(xyz-d50 .1 .2 .3), color(xyz-d50 .3 .2 .1))" },
        .{ .name = "xyz-d65", .invocation = "meta.call($mix, color(xyz-d65 .1 .2 .3), color(xyz-d65 .3 .2 .1))" },
        .{ .name = "variable", .invocation = "meta.call($mix, red, var(--color))" },
    };
    for (invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:meta\"; @use \"sass:color\"; $mix: meta.get-function(\"mix\", $module: \"color\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-mix-module-not-loaded.scss",
            "@use \"sass:meta\"; .a { value: meta.call(meta.get-function(\"mix\", $module: \"color\"), red, blue); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-mix-module-member.scss",
            "@use \"sass:meta\"; @use \"sass:color\"; .a { value: meta.call(meta.get-function(\"tone\", $module: \"color\"), red, blue); }",
            .scss,
            .{},
        ),
    );
    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-mix-argument-limit.scss",
            "@use \"sass:meta\"; @use \"sass:color\"; $mix: meta.get-function(\"mix\", $module: \"color\"); .a { value: meta.call($mix, red, blue); }",
            .scss,
            argument_limits,
        ),
    );

    const direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "direct-missing", .invocation = "color.mix(red)" },
        .{ .name = "direct-empty-splat", .invocation = "color.mix(()...)" },
        .{ .name = "direct-short-list-splat", .invocation = "color.mix((red,)...)" },
        .{ .name = "direct-overfull-list-splat", .invocation = "color.mix((red, blue, 25%, rgb)...)" },
        .{ .name = "direct-unknown-map-splat", .invocation = "color.mix((color1: red, color2: blue, other: 25%)...)" },
        .{ .name = "direct-invalid-map-key-splat", .invocation = "color.mix((1: red, color2: blue)...)" },
        .{ .name = "direct-positional-map-duplicate", .invocation = "color.mix(red, blue, (color2: green)...)" },
        .{ .name = "direct-unitless-weight", .invocation = "color.mix(red, blue, 25)" },
        .{ .name = "direct-method", .invocation = "color.mix(red, blue, $method: rgb)" },
        .{ .name = "direct-modern-color", .invocation = "color.mix(color(display-p3 .1 .2 .3), blue)" },
        .{ .name = "direct-deferred", .invocation = "color.mix(red, var(--color))" },
    };
    for (direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:color\"; .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    const legacy_direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "legacy-direct-empty-splat", .invocation = "mix(()...)" },
        .{ .name = "legacy-direct-short-list-splat", .invocation = "mix((red,)...)" },
        .{ .name = "legacy-direct-overfull-list-splat", .invocation = "mix((red, blue, 25%, rgb)...)" },
        .{ .name = "legacy-direct-unknown-map-splat", .invocation = "mix((color1: red, color2: blue, other: 25%)...)" },
        .{ .name = "legacy-direct-invalid-map-key-splat", .invocation = "mix((1: red, color2: blue)...)" },
        .{ .name = "legacy-direct-positional-map-duplicate", .invocation = "mix(red, blue, (color2: green)...)" },
        .{ .name = "legacy-direct-unitless-weight", .invocation = "mix((red, blue, 25)...)" },
        .{ .name = "legacy-direct-method", .invocation = "mix((color1: red, color2: blue, method: rgb)...)" },
        .{ .name = "legacy-direct-modern-color", .invocation = "mix((color(display-p3 .1 .2 .3), blue)...)" },
        .{ .name = "legacy-direct-deferred", .invocation = "mix((red, var(--color))...)" },
    };
    for (legacy_direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            ".a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "color-mix-direct-function-argument-limit.scss",
            "@use \"sass:color\"; .a { value: color.mix((red, blue)...); }",
            .scss,
            argument_limits,
        ),
    );
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "legacy-color-mix-direct-splat-argument-limit.scss",
            ".a { value: mix((red, blue)...); }",
            .scss,
            argument_limits,
        ),
    );
}

test "native Sass expands direct legacy color lighten splats once in source order" {
    const input =
        \\@use "sass:meta";
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\.values {
        \\  list: lighten((mark(1, #123456), mark(2, 10%))...);
        \\  map: lighten(("color": mark(3, hsl(120deg 50% 25%)), "amount": mark(4, 10%))...);
        \\  direct-map: lighten(mark(5, hwb(240deg 10% 20%)), ("amount": mark(6, 25%))...);
        \\  override: lighten($color: #123456, $amount: 25%, ("amount": mark(7, 10%))...);
        \\  unitless: lighten((red, 10)...);
        \\  unitful: lighten((red, 10px)...);
        \\  alpha: lighten((rgba(18, 52, 86, .5), 10%)...);
        \\  type: meta.type-of(lighten((red, 10%)...));
        \\  trace: $trace;
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "legacy-color-lighten-direct-splat.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{list:rgb(26.8269230769,77.5,128.1730769231);map:hsl(120,50%,35%);direct-map:#77e;override:rgb(26.8269230769,77.5,128.1730769231);unitless:#f33;unitful:#f33;alpha:rgba(26.8269230769,77.5,128.1730769231,.5);type:color;trace:1234567}",
        result.css(),
    );
    const diagnostics = result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 16), diagnostics.len);
    var global_warnings: usize = 0;
    var lighten_warnings: usize = 0;
    for (diagnostics) |diagnostic| {
        try std.testing.expectEqual(
            preprocessor.diagnostics.Severity.warning,
            diagnostic.severity,
        );
        try std.testing.expectEqual(
            preprocessor.diagnostics.Code.invalid_operation,
            diagnostic.code,
        );
        if (std.mem.eql(
            u8,
            diagnostic.message,
            "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        )) {
            global_warnings += 1;
        } else if (std.mem.eql(
            u8,
            diagnostic.message,
            "lighten() is deprecated. Use color.adjust($color, $lightness: $amount).",
        )) {
            lighten_warnings += 1;
        } else {
            return error.TestUnexpectedResult;
        }
    }
    try std.testing.expectEqual(@as(usize, 8), global_warnings);
    try std.testing.expectEqual(@as(usize, 8), lighten_warnings);

    const indented =
        \\$trace: 0
        \\@function mark($digit, $value)
        \\  $trace: $trace * 10 + $digit !global
        \\  @return $value
        \\.sass
        \\  list: lighten((mark(1, hsl(120deg 50% 25%)), mark(2, 10%))...)
        \\  map: lighten((color: mark(3, hwb(240deg 10% 20%)), amount: mark(4, 25%))...)
        \\  trace: $trace
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "legacy-color-lighten-direct-splat.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{list:hsl(120,50%,35%);map:#77e;trace:1234}",
        sass_result.css(),
    );
    const sass_diagnostics = sass_result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 4), sass_diagnostics.len);
    for (sass_diagnostics) |diagnostic| {
        try std.testing.expectEqual(
            preprocessor.diagnostics.Severity.warning,
            diagnostic.severity,
        );
        try std.testing.expectEqual(
            preprocessor.diagnostics.Code.invalid_operation,
            diagnostic.code,
        );
    }

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseDirectLegacyColorLightenSplatAllocationFailures,
        .{},
    );
}

fn exerciseDirectLegacyColorLightenSplatAllocationFailures(
    allocator: std.mem.Allocator,
) !void {
    const input =
        \\.allocation {
        \\  list: lighten((#123456, 10%)...);
        \\  map: lighten(("color": hsl(120deg 50% 25%), "amount": 10%)...);
        \\}
    ;
    var result = try compile(
        allocator,
        "legacy-color-lighten-direct-splat-allocation.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".allocation{list:rgb(26.8269230769,77.5,128.1730769231);map:hsl(120,50%,35%)}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 4), result.nativeDiagnostics().len);
}

test "native Sass meta call invokes legacy color lighten function references" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:color";
        \\@use "sass:color" as palette;
        \\$global: meta.get-function("lighten");
        \\$module: meta.get-function("lighten", $module: "color");
        \\$alias: meta.get-function("lighten", $module: "palette");
        \\@use "sass:color" as *;
        \\$star: meta.get-function("lighten");
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$list-args: (hsl(120deg 50% 25%), 10%);
        \\$map-args: ("color": hwb(240deg 10% 20%), "amount": 25%);
        \\.values {
        \\  global-exists: meta.function-exists("lighten");
        \\  module-exists: meta.function-exists("lighten", "color");
        \\  alias-exists: meta.function-exists("lighten", "palette");
        \\  type: meta.type-of($global);
        \\  global-module-same: $global == $module;
        \\  module-alias-same: $module == $alias;
        \\  star-module-same: $star == $module;
        \\  star-global-same: $star == $global;
        \\  inspect-global: meta.inspect($global);
        \\  inspect-module: meta.inspect($module);
        \\  global: meta.call($global, #123456, 10%);
        \\  named: meta.call($global, $amount: 10%, $color: #123456);
        \\  unitless: meta.call($global, red, 10);
        \\  unitful: meta.call($global, red, 10px);
        \\  transparent: meta.call($global, transparent, 10%);
        \\  alpha: meta.call($global, rgba(18, 52, 86, .5), 10%);
        \\  hsl: meta.call($global, hsl(120deg 50% 25%), 10%);
        \\  hwb: meta.call($global, hwb(240deg 10% 20%), 25%);
        \\  list-splat: meta.call($global, $list-args...);
        \\  map-splat: meta.call($global, $map-args...);
        \\  zero: meta.call($global, red, 0%);
        \\  full: meta.call($global, red, 100%);
        \\  ordered: meta.call(mark(1, $global), $amount: mark(3, 10%), $color: mark(2, #123456));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($global, red, 10%));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-color-lighten-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{global-exists:true;module-exists:true;alias-exists:true;type:function;global-module-same:false;module-alias-same:true;star-module-same:true;star-global-same:false;inspect-global:get-function(\"lighten\");inspect-module:get-function(\"lighten\");global:rgb(26.8269230769,77.5,128.1730769231);named:rgb(26.8269230769,77.5,128.1730769231);unitless:#f33;unitful:#f33;transparent:hsla(0,0%,10%,0);alpha:rgba(26.8269230769,77.5,128.1730769231,.5);hsl:hsl(120,50%,35%);hwb:#77e;list-splat:hsl(120,50%,35%);map-splat:#77e;zero:red;full:#fff;ordered:rgb(26.8269230769,77.5,128.1730769231);trace:132;result-type:color}",
        result.css(),
    );
    const diagnostics = result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 28), diagnostics.len);
    var global_warnings: usize = 0;
    var lighten_warnings: usize = 0;
    for (diagnostics) |diagnostic| {
        try std.testing.expectEqual(
            preprocessor.diagnostics.Severity.warning,
            diagnostic.severity,
        );
        try std.testing.expectEqual(
            preprocessor.diagnostics.Code.invalid_operation,
            diagnostic.code,
        );
        if (std.mem.eql(
            u8,
            diagnostic.message,
            "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        )) {
            global_warnings += 1;
        } else if (std.mem.eql(
            u8,
            diagnostic.message,
            "lighten() is deprecated. Use color.adjust($color, $lightness: $amount).",
        )) {
            lighten_warnings += 1;
        } else {
            return error.TestUnexpectedResult;
        }
    }
    try std.testing.expectEqual(@as(usize, 14), global_warnings);
    try std.testing.expectEqual(@as(usize, 14), lighten_warnings);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:color" as palette
        \\$lighten: m.get-function("lighten")
        \\$module: m.get-function("lighten", $module: "palette")
        \\$arguments: ("color": hwb(240deg 10% 20%), "amount": 25%)
        \\.sass
        \\  type: m.type-of($lighten)
        \\  module-type: m.type-of($module)
        \\  plain: m.call($lighten, hsl(120deg 50% 25%), 10%)
        \\  named: m.call($lighten, $color: #123456, $amount: 10%)
        \\  map: m.call($lighten, $arguments...)
        \\  module-inspect: m.inspect($module)
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-call-color-lighten-function.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{type:function;module-type:function;plain:hsl(120,50%,35%);named:rgb(26.8269230769,77.5,128.1730769231);map:#77e;module-inspect:get-function(\"lighten\")}",
        sass_result.css(),
    );
    const sass_diagnostics = sass_result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 6), sass_diagnostics.len);

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseColorLightenFunctionAllocationFailures,
        .{},
    );
}

fn exerciseColorLightenFunctionAllocationFailures(allocator: std.mem.Allocator) !void {
    const input =
        \\@use "sass:meta";
        \\$lighten: meta.get-function("lighten");
        \\.allocation {
        \\  percent: meta.call($lighten, #123456, 10%);
        \\  unitful: meta.call($lighten, red, 10px);
        \\}
    ;
    var result = try compile(
        allocator,
        "meta-call-color-lighten-allocation.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".allocation{percent:rgb(26.8269230769,77.5,128.1730769231);unitful:#f33}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 4), result.nativeDiagnostics().len);
}

test "native Sass meta call rejects unavailable color lighten forms arguments and limits" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "meta.call($lighten)" },
        .{ .name = "missing-amount", .invocation = "meta.call($lighten, red)" },
        .{ .name = "extra", .invocation = "meta.call($lighten, red, 10%, hsl)" },
        .{ .name = "unknown", .invocation = "meta.call($lighten, red, $other: 10%)" },
        .{ .name = "duplicate", .invocation = "meta.call($lighten, red, 10%, $amount: 20%)" },
        .{ .name = "empty-splat", .invocation = "meta.call($lighten, ()...)" },
        .{ .name = "null", .invocation = "meta.call($lighten, null, 10%)" },
        .{ .name = "boolean", .invocation = "meta.call($lighten, true, 10%)" },
        .{ .name = "number", .invocation = "meta.call($lighten, 1, 10%)" },
        .{ .name = "quoted", .invocation = "meta.call($lighten, \"red\", 10%)" },
        .{ .name = "unquoted", .invocation = "meta.call($lighten, red-name, 10%)" },
        .{ .name = "list", .invocation = "meta.call($lighten, (red, blue), 10%)" },
        .{ .name = "map", .invocation = "meta.call($lighten, (tone: red), 10%)" },
        .{ .name = "callable", .invocation = "meta.call($lighten, meta.get-function(\"inspect\", $module: \"meta\"), 10%)" },
        .{ .name = "null-amount", .invocation = "meta.call($lighten, red, null)" },
        .{ .name = "boolean-amount", .invocation = "meta.call($lighten, red, true)" },
        .{ .name = "color-amount", .invocation = "meta.call($lighten, red, blue)" },
        .{ .name = "string-amount", .invocation = "meta.call($lighten, red, \"10%\")" },
        .{ .name = "list-amount", .invocation = "meta.call($lighten, red, (10%, 20%))" },
        .{ .name = "map-amount", .invocation = "meta.call($lighten, red, (amount: 10%))" },
        .{ .name = "callable-amount", .invocation = "meta.call($lighten, red, meta.get-function(\"inspect\", $module: \"meta\"))" },
        .{ .name = "calculation-amount", .invocation = "meta.call($lighten, red, calc(5% + var(--amount)))" },
        .{ .name = "compound-amount", .invocation = "meta.call($lighten, red, math.div(10px, 1s))" },
        .{ .name = "negative-amount", .invocation = "meta.call($lighten, red, -1%)" },
        .{ .name = "high-amount", .invocation = "meta.call($lighten, red, 101%)" },
        .{ .name = "rgb-missing", .invocation = "meta.call($lighten, rgb(none 0 0), 10%)" },
        .{ .name = "lab", .invocation = "meta.call($lighten, lab(50% 10 20), 10%)" },
        .{ .name = "lch", .invocation = "meta.call($lighten, lch(50% 20 30deg), 10%)" },
        .{ .name = "oklab", .invocation = "meta.call($lighten, oklab(50% .1 .2), 10%)" },
        .{ .name = "oklch", .invocation = "meta.call($lighten, oklch(50% .1 30deg), 10%)" },
        .{ .name = "srgb", .invocation = "meta.call($lighten, color(srgb .1 .2 .3), 10%)" },
        .{ .name = "srgb-linear", .invocation = "meta.call($lighten, color(srgb-linear .1 .2 .3), 10%)" },
        .{ .name = "display-p3", .invocation = "meta.call($lighten, color(display-p3 .1 .2 .3), 10%)" },
        .{ .name = "a98-rgb", .invocation = "meta.call($lighten, color(a98-rgb .1 .2 .3), 10%)" },
        .{ .name = "prophoto-rgb", .invocation = "meta.call($lighten, color(prophoto-rgb .1 .2 .3), 10%)" },
        .{ .name = "rec2020", .invocation = "meta.call($lighten, color(rec2020 .1 .2 .3), 10%)" },
        .{ .name = "xyz-d50", .invocation = "meta.call($lighten, color(xyz-d50 .1 .2 .3), 10%)" },
        .{ .name = "xyz-d65", .invocation = "meta.call($lighten, color(xyz-d65 .1 .2 .3), 10%)" },
        .{ .name = "variable", .invocation = "meta.call($lighten, var(--color), 10%)" },
    };
    for (invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:meta\"; @use \"sass:math\"; $lighten: meta.get-function(\"lighten\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    const legacy_direct_invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "legacy-direct-empty-splat", .invocation = "lighten(()...)" },
        .{ .name = "legacy-direct-short-list-splat", .invocation = "lighten((red,)...)" },
        .{ .name = "legacy-direct-overfull-list-splat", .invocation = "lighten((red, 10%, extra)...)" },
        .{ .name = "legacy-direct-unknown-map-splat", .invocation = "lighten((color: red, other: 10%)...)" },
        .{ .name = "legacy-direct-invalid-map-key-splat", .invocation = "lighten((1: red, amount: 10%)...)" },
        .{ .name = "legacy-direct-positional-map-duplicate", .invocation = "lighten(red, 10%, (amount: 20%)...)" },
        .{ .name = "legacy-direct-negative-amount", .invocation = "lighten((red, -1%)...)" },
        .{ .name = "legacy-direct-high-amount", .invocation = "lighten((red, 101%)...)" },
        .{ .name = "legacy-direct-deferred-amount", .invocation = "lighten((red, var(--amount))...)" },
        .{ .name = "legacy-direct-missing-channel", .invocation = "lighten((rgb(none 0 0), 10%)...)" },
        .{ .name = "legacy-direct-modern-color", .invocation = "lighten((color(display-p3 .1 .2 .3), 10%)...)" },
    };
    for (legacy_direct_invalid) |case| {
        const input = try std.fmt.allocPrint(
            std.testing.allocator,
            ".a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(input);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, input, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-lighten-module-not-loaded.scss",
            "@use \"sass:meta\"; .a { value: meta.call(meta.get-function(\"lighten\", $module: \"color\"), red, 10%); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-lighten-module-member.scss",
            "@use \"sass:meta\"; @use \"sass:color\"; .a { value: meta.call(meta.get-function(\"tone\", $module: \"color\"), red, 10%); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-lighten-removed-module.scss",
            "@use \"sass:meta\"; @use \"sass:color\"; $lighten: meta.get-function(\"lighten\", $module: \"color\"); .a { value: meta.call($lighten, red, 10%); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-lighten-direct-module.scss",
            "@use \"sass:color\"; .a { value: color.lighten(red, 10%); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-lighten-direct-module-splat.scss",
            "@use \"sass:color\"; .a { value: color.lighten((red, 10%)...); }",
            .scss,
            .{},
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-lighten-argument-limit.scss",
            "@use \"sass:meta\"; $lighten: meta.get-function(\"lighten\"); .a { value: meta.call($lighten, red, 10%); }",
            .scss,
            argument_limits,
        ),
    );
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "legacy-color-lighten-direct-splat-argument-limit.scss",
            ".a { value: lighten((red, 10%)...); }",
            .scss,
            argument_limits,
        ),
    );
}

test "native Sass meta call invokes legacy color darken function references" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:color";
        \\@use "sass:color" as palette;
        \\$global: meta.get-function("darken");
        \\$module: meta.get-function("darken", $module: "color");
        \\$alias: meta.get-function("darken", $module: "palette");
        \\@use "sass:color" as *;
        \\$star: meta.get-function("darken");
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$list-args: (hsl(120deg 50% 25%), 10%);
        \\$map-args: ("color": hwb(240deg 10% 20%), "amount": 25%);
        \\.values {
        \\  global-exists: meta.function-exists("darken");
        \\  module-exists: meta.function-exists("darken", "color");
        \\  alias-exists: meta.function-exists("darken", "palette");
        \\  type: meta.type-of($global);
        \\  global-module-same: $global == $module;
        \\  module-alias-same: $module == $alias;
        \\  star-module-same: $star == $module;
        \\  star-global-same: $star == $global;
        \\  inspect-global: meta.inspect($global);
        \\  inspect-module: meta.inspect($module);
        \\  global: meta.call($global, #123456, 10%);
        \\  named: meta.call($global, $amount: 10%, $color: #123456);
        \\  unitless: meta.call($global, #123456, 10);
        \\  unitful: meta.call($global, #123456, 10px);
        \\  transparent: meta.call($global, transparent, 10%);
        \\  alpha: meta.call($global, rgba(18, 52, 86, .5), 10%);
        \\  hsl: meta.call($global, hsl(120deg 50% 25%), 10%);
        \\  hwb: meta.call($global, hwb(240deg 10% 20%), 25%);
        \\  list-splat: meta.call($global, $list-args...);
        \\  map-splat: meta.call($global, $map-args...);
        \\  zero: meta.call($global, red, 0%);
        \\  full: meta.call($global, red, 100%);
        \\  ordered: meta.call(mark(1, $global), $amount: mark(3, 10%), $color: mark(2, #123456));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($global, red, 10%));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-color-darken-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{global-exists:true;module-exists:true;alias-exists:true;type:function;global-module-same:false;module-alias-same:true;star-module-same:true;star-global-same:false;inspect-global:get-function(\"darken\");inspect-module:get-function(\"darken\");global:rgb(9.1730769231,26.5,43.8269230769);named:rgb(9.1730769231,26.5,43.8269230769);unitless:rgb(9.1730769231,26.5,43.8269230769);unitful:rgb(9.1730769231,26.5,43.8269230769);transparent:rgba(0,0,0,0);alpha:rgba(9.1730769231,26.5,43.8269230769,.5);hsl:hsl(120,50%,15%);hwb:hsl(240,77.7777777778%,20%);list-splat:hsl(120,50%,15%);map-splat:hsl(240,77.7777777778%,20%);zero:red;full:#000;ordered:rgb(9.1730769231,26.5,43.8269230769);trace:132;result-type:color}",
        result.css(),
    );
    const diagnostics = result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 28), diagnostics.len);
    var global_warnings: usize = 0;
    var darken_warnings: usize = 0;
    for (diagnostics) |diagnostic| {
        try std.testing.expectEqual(
            preprocessor.diagnostics.Severity.warning,
            diagnostic.severity,
        );
        try std.testing.expectEqual(
            preprocessor.diagnostics.Code.invalid_operation,
            diagnostic.code,
        );
        if (std.mem.eql(
            u8,
            diagnostic.message,
            "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        )) {
            global_warnings += 1;
        } else if (std.mem.eql(
            u8,
            diagnostic.message,
            "darken() is deprecated. Use color.adjust($color, $lightness: -$amount).",
        )) {
            darken_warnings += 1;
        } else {
            return error.TestUnexpectedResult;
        }
    }
    try std.testing.expectEqual(@as(usize, 14), global_warnings);
    try std.testing.expectEqual(@as(usize, 14), darken_warnings);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:color" as palette
        \\$darken: m.get-function("darken")
        \\$module: m.get-function("darken", $module: "palette")
        \\$arguments: ("color": hwb(240deg 10% 20%), "amount": 25%)
        \\.sass
        \\  type: m.type-of($darken)
        \\  module-type: m.type-of($module)
        \\  plain: m.call($darken, hsl(120deg 50% 25%), 10%)
        \\  named: m.call($darken, $color: #123456, $amount: 10%)
        \\  map: m.call($darken, $arguments...)
        \\  module-inspect: m.inspect($module)
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-call-color-darken-function.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{type:function;module-type:function;plain:hsl(120,50%,15%);named:rgb(9.1730769231,26.5,43.8269230769);map:hsl(240,77.7777777778%,20%);module-inspect:get-function(\"darken\")}",
        sass_result.css(),
    );
    const sass_diagnostics = sass_result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 6), sass_diagnostics.len);

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseColorDarkenFunctionAllocationFailures,
        .{},
    );
}

fn exerciseColorDarkenFunctionAllocationFailures(allocator: std.mem.Allocator) !void {
    const input =
        \\@use "sass:meta";
        \\$darken: meta.get-function("darken");
        \\.allocation {
        \\  percent: meta.call($darken, #123456, 10%);
        \\  unitful: meta.call($darken, red, 10px);
        \\}
    ;
    var result = try compile(
        allocator,
        "meta-call-color-darken-allocation.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".allocation{percent:rgb(9.1730769231,26.5,43.8269230769);unitful:#c00}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 4), result.nativeDiagnostics().len);
}

test "native Sass meta call rejects unavailable color darken forms arguments and limits" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "meta.call($darken)" },
        .{ .name = "missing-amount", .invocation = "meta.call($darken, red)" },
        .{ .name = "extra", .invocation = "meta.call($darken, red, 10%, hsl)" },
        .{ .name = "unknown", .invocation = "meta.call($darken, red, $other: 10%)" },
        .{ .name = "duplicate", .invocation = "meta.call($darken, red, 10%, $amount: 20%)" },
        .{ .name = "empty-splat", .invocation = "meta.call($darken, ()...)" },
        .{ .name = "null", .invocation = "meta.call($darken, null, 10%)" },
        .{ .name = "boolean", .invocation = "meta.call($darken, true, 10%)" },
        .{ .name = "number", .invocation = "meta.call($darken, 1, 10%)" },
        .{ .name = "quoted", .invocation = "meta.call($darken, \"red\", 10%)" },
        .{ .name = "unquoted", .invocation = "meta.call($darken, red-name, 10%)" },
        .{ .name = "list", .invocation = "meta.call($darken, (red, blue), 10%)" },
        .{ .name = "map", .invocation = "meta.call($darken, (tone: red), 10%)" },
        .{ .name = "callable", .invocation = "meta.call($darken, meta.get-function(\"inspect\", $module: \"meta\"), 10%)" },
        .{ .name = "null-amount", .invocation = "meta.call($darken, red, null)" },
        .{ .name = "boolean-amount", .invocation = "meta.call($darken, red, true)" },
        .{ .name = "color-amount", .invocation = "meta.call($darken, red, blue)" },
        .{ .name = "string-amount", .invocation = "meta.call($darken, red, \"10%\")" },
        .{ .name = "list-amount", .invocation = "meta.call($darken, red, (10%, 20%))" },
        .{ .name = "map-amount", .invocation = "meta.call($darken, red, (amount: 10%))" },
