        \\@use "sass:color" as *;
        \\$star: meta.get-function("grayscale");
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$color-list: (#123456,);
