        },
        .{
            .name = "meta-call-module-variables-duplicate.scss",
            .input = "@use \"sass:meta\"; $reference: meta.get-function(\"module-variables\", $module: \"meta\"); .a { value: meta.inspect(meta.call($reference, \"meta\", $module: \"meta\")); }",
