            std.testing.allocator,
            "meta-module-variables-collection-limit.scss",
            "@use \"sass:meta\"; @use \"sass:math\"; .a { value: meta.inspect(meta.module-variables(\"math\")); }",
            .scss,
            collection_limits,
        ),
    );
}

