        .{ .name = "deferred-color", .invocation = "color.is-missing(var(--color), \"red\")" },
        .{ .name = "null-channel", .invocation = "color.is-missing(red, null)" },
        .{ .name = "unquoted-channel", .invocation = "color.is-missing(red, red)" },
        .{ .name = "number-channel", .invocation = "color.is-missing(red, 1)" },
        .{ .name = "color-channel", .invocation = "color.is-missing(red, blue)" },
        .{ .name = "list-channel", .invocation = "color.is-missing(red, (\"red\", \"green\"))" },
        .{ .name = "map-channel", .invocation = "color.is-missing(red, (channel: \"red\"))" },
        .{ .name = "deferred-channel", .invocation = "color.is-missing(red, var(--channel))" },
        .{ .name = "case-sensitive", .invocation = "color.is-missing(lab(none 10 20), \"LIGHTNESS\")" },
        .{ .name = "wrong-space-channel", .invocation = "color.is-missing(lab(none 10 20), \"red\")" },
    };
    for (invalid) |case| {
        const case_source = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:color\"; @use \"sass:meta\"; $is-missing: meta.get-function(\"is-missing\", $module: \"color\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(case_source);
        const name = try std.fmt.allocPrint(
            std.testing.allocator,
            "meta-call-color-is-missing-{s}.scss",
            .{case.name},
        );
        defer std.testing.allocator.free(name);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, name, case_source, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-is-missing-global-reference.scss",
            "@use \"sass:meta\"; $is-missing: meta.get-function(\"is-missing\"); .a { value: meta.call($is-missing, red, \"red\"); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-is-missing-module-not-loaded.scss",
            "@use \"sass:meta\"; $is-missing: meta.get-function(\"is-missing\", $module: \"color\"); .a { value: meta.call($is-missing, red, \"red\"); }",
            .scss,
            .{},
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 2;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-is-missing-argument-limit.scss",
            "@use \"sass:color\"; @use \"sass:meta\"; $is-missing: meta.get-function(\"is-missing\", $module: \"color\"); .a { value: meta.call($is-missing, red, \"red\"); }",
            .scss,
            argument_limits,
        ),
    );

    var temporary_limits = sass_evaluator.Limits{};
    temporary_limits.max_temporary_bytes = 8;
    try std.testing.expectError(
        error.TemporaryLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-is-missing-temporary-limit.scss",
            "@use \"sass:color\"; .a { value: color.is-missing(lab(none 10 20), \"lightness\"); }",
            .scss,
            temporary_limits,
        ),
    );
}

test "native Sass color is-in-gamut function checks direct and reflected bounded spaces" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:color";
        \\@use "sass:color" as palette;
        \\@use "sass:color" as *;
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$module: meta.get-function("is-in-gamut", $module: "color");
        \\$alias: meta.get-function("is_in_gamut", $module: "palette");
        \\$star: meta.get-function("is-in-gamut");
        \\$list-args: (color(display-p3 0 1 0), rgb);
        \\$map-args: (space: display-p3, color: color(display-p3 0 1 0));
        \\.values {
        \\  exists: meta.function-exists("is-in-gamut", "color");
        \\  alias-exists: meta.function-exists("is_in_gamut", "palette");
        \\  global-exists: meta.function-exists("is-in-gamut");
        \\  type: meta.type-of($module);
        \\  same: $module == $alias;
        \\  star-same: $module == $star;
        \\  rgb: color.is-in-gamut(#369);
        \\  hsl-in: color.is-in-gamut(hsl(120 50% 50%));
        \\  hsl-saturation: color.is-in-gamut(hsl(120 120% 50%));
        \\  hsl-lightness: color.is-in-gamut(hsl(120 50% -10%));
        \\  hwb-in: color.is-in-gamut(hwb(120 20% 30%));
        \\  hwb-negative: color.is-in-gamut(hwb(120 -10% 20%));
        \\  p3-in: color.is-in-gamut(color(display-p3 0 1 0));
        \\  p3-out: color.is-in-gamut(color(display-p3 1.2 -.1 .5));
        \\  p3-green-rgb: color.is-in-gamut(color(display-p3 0 1 0), rgb);
        \\  p3-green-hsl: color.is-in-gamut(color(display-p3 0 1 0), hsl);
        \\  p3-green-hwb: color.is-in-gamut(color(display-p3 0 1 0), hwb);
        \\  p3-green-srgb: color.is-in-gamut(color(display-p3 0 1 0), srgb);
        \\  p3-green-linear: color.is-in-gamut(color(display-p3 0 1 0), srgb-linear);
        \\  p3-green-p3: color.is-in-gamut(color(display-p3 0 1 0), display-p3);
        \\  p3-green-a98: color.is-in-gamut(color(display-p3 0 1 0), a98-rgb);
        \\  p3-green-prophoto: color.is-in-gamut(color(display-p3 0 1 0), prophoto-rgb);
        \\  p3-green-rec2020: color.is-in-gamut(color(display-p3 0 1 0), rec2020);
        \\  p3-green-lab: color.is-in-gamut(color(display-p3 0 1 0), lab);
        \\  p3-green-lch: color.is-in-gamut(color(display-p3 0 1 0), lch);
        \\  p3-green-oklab: color.is-in-gamut(color(display-p3 0 1 0), oklab);
        \\  p3-green-oklch: color.is-in-gamut(color(display-p3 0 1 0), oklch);
        \\  p3-green-xyz50: color.is-in-gamut(color(display-p3 0 1 0), xyz-d50);
        \\  p3-green-xyz65: color.is-in-gamut(color(display-p3 0 1 0), xyz-d65);
        \\  p3-green-xyz: color.is-in-gamut(color(display-p3 0 1 0), xyz);
        \\  missing-default: color.is-in-gamut(color(display-p3 none .2 .3 / none));
        \\  missing-same: color.is-in-gamut(color(display-p3 none .2 .3 / none), display-p3);
        \\  alpha: color.is-in-gamut(color(display-p3 .1 .2 .3 / none));
        \\  null-space: color.is-in-gamut(red, null);
        \\  uppercase: color.is-in-gamut(red, DISPLAY-P3);
        \\  tolerance-upper: color.is-in-gamut(color(srgb 1.000000000004 0 0));
        \\  beyond-upper: color.is-in-gamut(color(srgb 1.000000000006 0 0));
        \\  tolerance-lower: color.is-in-gamut(color(srgb -.000000000004 0 0));
        \\  beyond-lower: color.is-in-gamut(color(srgb -.000000000006 0 0));
        \\  alias: palette.is_in_gamut(color(display-p3 0 1 0), rgb);
        \\  star: is-in-gamut(red);
        \\  reflected: meta.call($module, color(display-p3 0 1 0), rgb);
        \\  named: meta.call($module, $space: display-p3, $color: color(display-p3 0 1 0));
        \\  list-splat: meta.call($module, $list-args...);
        \\  map-splat: meta.call($module, $map-args...);
        \\  ordered: meta.call(mark(1, $module), mark(2, color(display-p3 0 1 0)), mark(3, display-p3));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($module, red));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-color-is-in-gamut-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{exists:true;alias-exists:true;global-exists:true;type:function;same:true;star-same:true;rgb:true;hsl-in:true;hsl-saturation:false;hsl-lightness:false;hwb-in:true;hwb-negative:false;p3-in:true;p3-out:false;p3-green-rgb:false;p3-green-hsl:false;p3-green-hwb:false;p3-green-srgb:false;p3-green-linear:false;p3-green-p3:true;p3-green-a98:false;p3-green-prophoto:true;p3-green-rec2020:true;p3-green-lab:true;p3-green-lch:true;p3-green-oklab:true;p3-green-oklch:true;p3-green-xyz50:true;p3-green-xyz65:true;p3-green-xyz:true;missing-default:true;missing-same:true;alpha:true;null-space:true;uppercase:true;tolerance-upper:true;beyond-upper:false;tolerance-lower:true;beyond-lower:false;alias:false;star:true;reflected:false;named:true;list-splat:false;map-splat:true;ordered:true;trace:123;result-type:bool}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);

    const plain_css =
        \\@use "sass:meta";
        \\.plain {
        \\  exists: meta.function-exists("is-in-gamut");
        \\  value: is-in-gamut(red);
        \\}
    ;
    var plain_result = try compile(
        std.testing.allocator,
        "color-is-in-gamut-plain-css.scss",
        plain_css,
        .scss,
        .{},
    );
    defer plain_result.deinit();
    try std.testing.expectEqualStrings(
        ".plain{exists:false;value:is-in-gamut(red)}",
        plain_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), plain_result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:color" as palette
        \\$reference: m.get-function("is-in-gamut", $module: "palette")
        \\.sass
        \\  exists: m.function-exists("is-in-gamut", "palette")
        \\  global-exists: m.function-exists("is-in-gamut")
        \\  type: m.type-of($reference)
        \\  default: m.call($reference, color(display-p3 0 1 0))
        \\  named: m.call($reference, $space: rgb, $color: color(display-p3 0 1 0))
        \\  direct: palette.is-in-gamut(color(display-p3 0 1 0), display-p3)
        \\  unbounded: palette.is_in_gamut(color(display-p3 0 1 0), oklab)
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-call-color-is-in-gamut-function.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{exists:true;global-exists:false;type:function;default:true;named:false;direct:true;unbounded:true}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseColorIsInGamutFunctionAllocationFailures,
        .{},
    );
}

fn exerciseColorIsInGamutFunctionAllocationFailures(allocator: std.mem.Allocator) !void {
    const input =
        \\@use "sass:color";
        \\@use "sass:meta";
        \\$reference: meta.get-function("is-in-gamut", $module: "color");
        \\.allocation {
        \\  direct: color.is-in-gamut(color(display-p3 0 1 0), rgb);
        \\  reflected: meta.call($reference, color(display-p3 0 1 0), display-p3);
        \\}
    ;
    var result = try compile(
        allocator,
        "meta-call-color-is-in-gamut-allocation.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".allocation{direct:false;reflected:true}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);
}

test "native Sass color is-in-gamut function rejects invalid and unavailable invocations" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "color.is-in-gamut()" },
        .{ .name = "extra", .invocation = "meta.call($is-in-gamut, red, rgb, extra)" },
        .{ .name = "unknown", .invocation = "color.is-in-gamut($other: red)" },
        .{ .name = "duplicate", .invocation = "meta.call($is-in-gamut, red, $color: blue)" },
        .{ .name = "null-color", .invocation = "color.is-in-gamut(null)" },
        .{ .name = "boolean-color", .invocation = "color.is-in-gamut(true)" },
        .{ .name = "number-color", .invocation = "color.is-in-gamut(1)" },
        .{ .name = "string-color", .invocation = "color.is-in-gamut(\"red\")" },
        .{ .name = "list-color", .invocation = "color.is-in-gamut((red, blue))" },
        .{ .name = "map-color", .invocation = "color.is-in-gamut((tone: red))" },
        .{ .name = "deferred-color", .invocation = "color.is-in-gamut(var(--color))" },
        .{ .name = "boolean-space", .invocation = "color.is-in-gamut(red, true)" },
        .{ .name = "number-space", .invocation = "color.is-in-gamut(red, 1)" },
        .{ .name = "quoted-space", .invocation = "color.is-in-gamut(red, \"rgb\")" },
        .{ .name = "color-space", .invocation = "color.is-in-gamut(red, blue)" },
        .{ .name = "list-space", .invocation = "color.is-in-gamut(red, (rgb, hsl))" },
        .{ .name = "map-space", .invocation = "color.is-in-gamut(red, (space: rgb))" },
        .{ .name = "deferred-space", .invocation = "color.is-in-gamut(red, var(--space))" },
        .{ .name = "unknown-space", .invocation = "color.is-in-gamut(red, custom)" },
        .{ .name = "underscore-space", .invocation = "color.is-in-gamut(red, display_p3)" },
        .{
            .name = "missing-cross-space",
            .invocation = "color.is-in-gamut(color(display-p3 none .2 .3), srgb)",
        },
    };
    for (invalid) |case| {
        const case_source = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:color\"; @use \"sass:meta\"; $is-in-gamut: meta.get-function(\"is-in-gamut\", $module: \"color\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(case_source);
        const name = try std.fmt.allocPrint(
            std.testing.allocator,
            "meta-call-color-is-in-gamut-{s}.scss",
            .{case.name},
        );
        defer std.testing.allocator.free(name);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, name, case_source, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-is-in-gamut-global-reference.scss",
            "@use \"sass:meta\"; $is-in-gamut: meta.get-function(\"is-in-gamut\"); .a { value: meta.call($is-in-gamut, red); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-is-in-gamut-module-not-loaded.scss",
            "@use \"sass:meta\"; $is-in-gamut: meta.get-function(\"is-in-gamut\", $module: \"color\"); .a { value: meta.call($is-in-gamut, red); }",
            .scss,
            .{},
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 2;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-is-in-gamut-argument-limit.scss",
            "@use \"sass:color\"; @use \"sass:meta\"; $is-in-gamut: meta.get-function(\"is-in-gamut\", $module: \"color\"); .a { value: meta.call($is-in-gamut, red, rgb); }",
            .scss,
            argument_limits,
        ),
    );
}

test "native Sass color to-gamut function maps direct and reflected bounded spaces" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:color";
        \\@use "sass:color" as palette;
        \\@use "sass:color" as *;
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$module: meta.get-function("to-gamut", $module: "color");
        \\$alias: meta.get-function("to_gamut", $module: "palette");
        \\$star: meta.get-function("to-gamut");
        \\$list-args: (color(display-p3 1.2 -.1 .5), srgb, clip);
        \\$map-args: (method: clip, color: color(display-p3 1.2 -.1 .5), space: display-p3);
        \\.values {
        \\  exists: meta.function-exists("to-gamut", "color");
        \\  alias-exists: meta.function-exists("to_gamut", "palette");
        \\  global-exists: meta.function-exists("to-gamut");
        \\  type: meta.type-of($module);
        \\  same: $module == $alias;
        \\  star-same: $module == $star;
        \\  red: color.to-gamut(red, $method: clip);
        \\  p3-clip: color.to-gamut(color(display-p3 1.2 -.1 .5), $method: clip);
        \\  p3-local: color.to-gamut(color(display-p3 1.2 -.1 .5), $method: local-minde);
        \\  p3-green-rgb-clip: color.to-gamut(color(display-p3 0 1 0), rgb, clip);
        \\  p3-green-rgb-local: color.to-gamut(color(display-p3 0 1 0), rgb, local-minde);
        \\  hsl-clip: color.to-gamut(hsl(120 120% -10%), $method: clip);
        \\  hwb-clip: color.to-gamut(hwb(120 -10% 120%), $method: clip);
        \\  unbounded: color.to-gamut(color(display-p3 1.2 -.1 .5), oklab, clip);
        \\  alpha: color.to-gamut(color(display-p3 1.2 -.1 .5 / .4), $method: clip);
        \\  uppercase-space: color.to-gamut(color(display-p3 1.2 -.1 .5), DISPLAY-P3, clip);
        \\  alias: palette.to_gamut(color(display-p3 1.2 -.1 .5), $method: clip);
        \\  star: to-gamut(color(display-p3 1.2 -.1 .5), $method: local-minde);
        \\  reflected: meta.call($module, color(display-p3 1.2 -.1 .5), display-p3, clip);
        \\  named: meta.call($module, $method: clip, $space: display-p3, $color: color(display-p3 1.2 -.1 .5));
        \\  list-splat: meta.call($module, $list-args...);
        \\  map-splat: meta.call($module, $map-args...);
        \\  ordered: meta.call(mark(1, $module), mark(2, color(display-p3 1.2 -.1 .5)), mark(3, display-p3), mark(4, clip));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($module, red, $method: clip));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-color-to-gamut-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{exists:true;alias-exists:true;global-exists:true;type:function;same:true;star-same:true;red:red;p3-clip:color(display-p3 1 0 .5);p3-local:color(display-p3 1 .4368902261 .568893654);p3-green-rgb-clip:color(display-p3 .4584015902 .9852645833 .2982947078);p3-green-rgb-local:color(display-p3 .4514736911 .9712271355 .3318864125);hsl-clip:#000;hwb-clip:#000;unbounded:color(display-p3 1.2 -0.1 .5);alpha:color(display-p3 1 0 .5/.4);uppercase-space:color(display-p3 1 0 .5);alias:color(display-p3 1 0 .5);star:color(display-p3 1 .4368902261 .568893654);reflected:color(display-p3 1 0 .5);named:color(display-p3 1 0 .5);list-splat:color(display-p3 .9174875573 .2002868077 .4897982442);map-splat:color(display-p3 1 0 .5);ordered:color(display-p3 1 0 .5);trace:1234;result-type:color}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);

    const plain_css =
        \\@use "sass:meta";
        \\.plain {
        \\  exists: meta.function-exists("to-gamut");
        \\  value: to-gamut(red);
        \\}
    ;
    var plain_result = try compile(
        std.testing.allocator,
        "color-to-gamut-plain-css.scss",
        plain_css,
        .scss,
        .{},
    );
    defer plain_result.deinit();
    try std.testing.expectEqualStrings(
        ".plain{exists:false;value:to-gamut(red)}",
        plain_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), plain_result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:color" as palette
        \\$reference: m.get-function("to-gamut", $module: "palette")
        \\.sass
        \\  exists: m.function-exists("to-gamut", "palette")
        \\  global-exists: m.function-exists("to-gamut")
        \\  type: m.type-of($reference)
        \\  clipped: m.call($reference, color(display-p3 1.2 -.1 .5), $method: clip)
        \\  local: m.call($reference, $method: local-minde, $color: color(display-p3 1.2 -.1 .5))
        \\  direct: palette.to-gamut(color(display-p3 0 1 0), rgb, clip)
        \\  unbounded: palette.to_gamut(color(display-p3 1.2 -.1 .5), xyz, local-minde)
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-call-color-to-gamut-function.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{exists:true;global-exists:false;type:function;clipped:color(display-p3 1 0 .5);local:color(display-p3 1 .4368902261 .568893654);direct:color(display-p3 .4584015902 .9852645833 .2982947078);unbounded:color(display-p3 1.2 -0.1 .5)}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseColorToGamutFunctionAllocationFailures,
        .{},
    );
}

fn exerciseColorToGamutFunctionAllocationFailures(allocator: std.mem.Allocator) !void {
    const input =
        \\@use "sass:color";
        \\@use "sass:meta";
        \\$reference: meta.get-function("to-gamut", $module: "color");
        \\.allocation {
        \\  direct: color.to-gamut(color(display-p3 1.2 -.1 .5), $method: clip);
        \\  reflected: meta.call($reference, color(display-p3 1.2 -.1 .5), rgb, local-minde);
        \\}
    ;
    var result = try compile(
        allocator,
        "meta-call-color-to-gamut-allocation.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".allocation{direct:color(display-p3 1 0 .5);reflected:color(display-p3 .9339934588 .5040521527 .5929350611)}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);
}

test "native Sass color to-gamut function rejects invalid and unavailable invocations" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "color.to-gamut()" },
        .{ .name = "missing-method", .invocation = "color.to-gamut(red)" },
        .{ .name = "null-method", .invocation = "color.to-gamut(red, $method: null)" },
        .{ .name = "extra", .invocation = "meta.call($to-gamut, red, rgb, clip, extra)" },
        .{ .name = "unknown", .invocation = "color.to-gamut(red, $other: clip)" },
        .{ .name = "duplicate", .invocation = "meta.call($to-gamut, red, $color: blue, $method: clip)" },
        .{ .name = "null-color", .invocation = "color.to-gamut(null, $method: clip)" },
        .{ .name = "boolean-color", .invocation = "color.to-gamut(true, $method: clip)" },
        .{ .name = "number-color", .invocation = "color.to-gamut(1, $method: clip)" },
        .{ .name = "string-color", .invocation = "color.to-gamut(\"red\", $method: clip)" },
        .{ .name = "deferred-color", .invocation = "color.to-gamut(var(--color), $method: clip)" },
        .{ .name = "boolean-space", .invocation = "color.to-gamut(red, true, clip)" },
        .{ .name = "quoted-space", .invocation = "color.to-gamut(red, \"rgb\", clip)" },
        .{ .name = "unknown-space", .invocation = "color.to-gamut(red, custom, clip)" },
        .{ .name = "underscore-space", .invocation = "color.to-gamut(red, display_p3, clip)" },
        .{ .name = "boolean-method", .invocation = "color.to-gamut(red, $method: true)" },
        .{ .name = "quoted-method", .invocation = "color.to-gamut(red, $method: \"clip\")" },
        .{ .name = "unknown-method", .invocation = "color.to-gamut(red, $method: custom)" },
        .{ .name = "uppercase-method", .invocation = "color.to-gamut(red, $method: CLIP)" },
        .{
            .name = "missing-same-space",
            .invocation = "color.to-gamut(color(display-p3 none 1.2 -.1), $method: clip)",
        },
        .{
            .name = "missing-cross-space",
            .invocation = "color.to-gamut(color(display-p3 none 1.2 -.1), srgb, local-minde)",
        },
        .{
            .name = "legacy-powerless-local-minde",
            .invocation = "color.to-gamut(hsl(120 120% -10%), $method: local-minde)",
        },
    };
    for (invalid) |case| {
        const case_source = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:color\"; @use \"sass:meta\"; $to-gamut: meta.get-function(\"to-gamut\", $module: \"color\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(case_source);
        const name = try std.fmt.allocPrint(
            std.testing.allocator,
            "meta-call-color-to-gamut-{s}.scss",
            .{case.name},
        );
        defer std.testing.allocator.free(name);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, name, case_source, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-to-gamut-global-reference.scss",
            "@use \"sass:meta\"; $to-gamut: meta.get-function(\"to-gamut\"); .a { value: meta.call($to-gamut, red, $method: clip); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-to-gamut-module-not-loaded.scss",
            "@use \"sass:meta\"; $to-gamut: meta.get-function(\"to-gamut\", $module: \"color\"); .a { value: meta.call($to-gamut, red, $method: clip); }",
            .scss,
            .{},
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 3;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-to-gamut-argument-limit.scss",
            "@use \"sass:color\"; @use \"sass:meta\"; $to-gamut: meta.get-function(\"to-gamut\", $module: \"color\"); .a { value: meta.call($to-gamut, red, rgb, clip); }",
            .scss,
            argument_limits,
        ),
    );
}

test "native Sass color channel function queries direct and reflected spaces" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:color";
        \\@use "sass:color" as palette;
        \\@use "sass:color" as *;
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$channel-name: red;
        \\$module: meta.get-function("channel", $module: "color");
        \\$alias: meta.get-function("channel", $module: "palette");
        \\$star: meta.get-function("channel");
        \\$list-args: (color(display-p3 .1 .2 .3 / .4), "green");
        \\$map-args: (space: hsl, channel: "hue", color: red);
        \\.values {
        \\  exists: meta.function-exists("channel", "color");
        \\  alias-exists: meta.function-exists("channel", "palette");
        \\  global-exists: meta.function-exists("channel");
        \\  type: meta.type-of($module);
        \\  same: $module == $alias;
        \\  star-same: $module == $star;
        \\  rgb-red: color.channel(rgb(12.5 20 30 / .4), "red");
        \\  rgb-alpha: color.channel(rgb(12.5 20 30 / .4), "alpha");
        \\  hsl-hue: color.channel(hsl(25deg 20% 30%), "hue");
        \\  hsl-saturation: color.channel(hsl(25deg 20% 30%), "saturation");
        \\  hsl-lightness: color.channel(hsl(25deg 20% 30%), "lightness");
        \\  hwb-hue: color.channel(hwb(25deg 20% 30%), "hue");
        \\  hwb-whiteness: color.channel(hwb(25deg 20% 30%), "whiteness");
        \\  hwb-blackness: color.channel(hwb(25deg 20% 30%), "blackness");
        \\  lab-lightness: color.channel(lab(25% 20 30), "lightness");
        \\  lab-a: color.channel(lab(25% 20 30), "a");
        \\  lab-b: color.channel(lab(25% 20 30), "b");
        \\  lch-lightness: color.channel(lch(25% 20 30deg), "lightness");
        \\  lch-chroma: color.channel(lch(25% 20 30deg), "chroma");
        \\  lch-hue: color.channel(lch(25% 20 30deg), "hue");
        \\  oklab-lightness: color.channel(oklab(.25 .2 .3), "lightness");
        \\  oklab-a: color.channel(oklab(.25 .2 .3), "a");
        \\  oklab-b: color.channel(oklab(.25 .2 .3), "b");
        \\  oklch-lightness: color.channel(oklch(.25 .2 30deg), "lightness");
        \\  oklch-chroma: color.channel(oklch(.25 .2 30deg), "chroma");
        \\  oklch-hue: color.channel(oklch(.25 .2 30deg), "hue");
        \\  srgb-red: color.channel(color(srgb .1 .2 .3), "red");
        \\  linear-green: color.channel(color(srgb-linear .1 .2 .3), "green");
        \\  p3-blue: color.channel(color(display-p3 .1 .2 .3), "blue");
        \\  p3-extended: color.channel(color(display-p3 1.2 -.1 .5), "red");
        \\  a98-red: color.channel(color(a98-rgb .1 .2 .3), "red");
        \\  prophoto-green: color.channel(color(prophoto-rgb .1 .2 .3), "green");
        \\  rec2020-blue: color.channel(color(rec2020 .1 .2 .3), "blue");
        \\  d50-x: color.channel(color(xyz-d50 .1 .2 .3), "x");
        \\  d50-y: color.channel(color(xyz-d50 .1 .2 .3), "y");
        \\  d50-z: color.channel(color(xyz-d50 .1 .2 .3), "z");
        \\  xyz-x: color.channel(color(xyz .1 .2 .3), "x");
        \\  convert-rgb-red: color.channel(color(display-p3 .1 .2 .3), "red", $space: rgb);
        \\  convert-hsl-hue: color.channel(red, "hue", hsl);
        \\  convert-p3-green: color.channel(red, "green", DISPLAY-P3);
        \\  convert-xyz-alias: color.channel(red, "x", XYZ-D65);
        \\  null-space: color.channel(red, "red", null);
        \\  alpha-space: color.channel(rgb(1 2 3 / .4), "alpha", oklab);
        \\  escaped: color.channel(red, "\72 ed");
        \\  interpolated: color.channel(red, "#{$channel-name}");
        \\  alias: palette.channel(color(display-p3 .1 .2 .3), "red");
        \\  star: channel(color(display-p3 .1 .2 .3), "red");
        \\  reflected: meta.call($module, color(display-p3 .1 .2 .3), "red");
        \\  named: meta.call($module, $space: hsl, $channel: "hue", $color: red);
        \\  list-splat: meta.call($module, $list-args...);
        \\  map-splat: meta.call($module, $map-args...);
        \\  ordered: meta.call(mark(1, $module), mark(2, red), mark(3, "red"), $space: mark(4, rgb));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($module, red, "red"));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-color-channel-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{exists:true;alias-exists:true;global-exists:true;type:function;same:true;star-same:true;rgb-red:12.5;rgb-alpha:.4;hsl-hue:25deg;hsl-saturation:20%;hsl-lightness:30%;hwb-hue:25deg;hwb-whiteness:20%;hwb-blackness:30%;lab-lightness:25%;lab-a:20;lab-b:30;lch-lightness:25%;lch-chroma:20;lch-hue:30deg;oklab-lightness:25%;oklab-a:.2;oklab-b:.3;oklch-lightness:25%;oklch-chroma:.2;oklch-hue:30deg;srgb-red:.1;linear-green:.2;p3-blue:.3;p3-extended:1.2;a98-red:.1;prophoto-green:.2;rec2020-blue:.3;d50-x:.1;d50-y:.2;d50-z:.3;xyz-x:.1;convert-rgb-red:15.1358007651;convert-hsl-hue:0deg;convert-p3-green:.2002868077;convert-xyz-alias:.4123907993;null-space:255;alpha-space:.4;escaped:255;interpolated:255;alias:.1;star:.1;reflected:.1;named:0deg;list-splat:.2;map-splat:0deg;ordered:255;trace:1234;result-type:number}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);

    const plain_css =
        \\@use "sass:meta";
        \\.plain {
        \\  exists: meta.function-exists("channel");
        \\  value: channel(red, "red");
        \\}
    ;
    var plain_result = try compile(
        std.testing.allocator,
        "color-channel-plain-css.scss",
        plain_css,
        .scss,
        .{},
    );
    defer plain_result.deinit();
    try std.testing.expectEqualStrings(
        ".plain{exists:false;value:channel(red, \"red\")}",
        plain_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), plain_result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:color" as palette
        \\$reference: m.get-function("channel", $module: "palette")
        \\.sass
        \\  exists: m.function-exists("channel", "palette")
        \\  global-exists: m.function-exists("channel")
        \\  type: m.type-of($reference)
        \\  red: m.call($reference, red, "red")
        \\  hue: palette.channel(red, "hue", hsl)
        \\  p3: palette.channel(red, "red", display-p3)
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-call-color-channel-function.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{exists:true;global-exists:false;type:function;red:255;hue:0deg;p3:.9174875573}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseColorChannelFunctionAllocationFailures,
        .{},
    );
}

fn exerciseColorChannelFunctionAllocationFailures(allocator: std.mem.Allocator) !void {
    const input =
        \\@use "sass:color";
        \\@use "sass:meta";
        \\$reference: meta.get-function("channel", $module: "color");
        \\.allocation {
        \\  direct: color.channel(color(display-p3 .1 .2 .3), "red");
        \\  reflected: meta.call($reference, red, "green", display-p3);
        \\}
    ;
    var result = try compile(
        allocator,
        "meta-call-color-channel-allocation.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".allocation{direct:.1;reflected:.2002868077}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);
}

test "native Sass color channel function rejects invalid and unavailable invocations" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "color.channel()" },
        .{ .name = "missing-channel", .invocation = "color.channel(red)" },
        .{ .name = "extra", .invocation = "meta.call($channel, red, \"red\", rgb, extra)" },
        .{ .name = "unknown", .invocation = "color.channel(red, \"red\", $other: rgb)" },
        .{ .name = "duplicate", .invocation = "meta.call($channel, red, \"red\", $color: blue)" },
        .{ .name = "null-color", .invocation = "color.channel(null, \"red\")" },
        .{ .name = "boolean-color", .invocation = "color.channel(true, \"red\")" },
        .{ .name = "number-color", .invocation = "color.channel(1, \"red\")" },
        .{ .name = "string-color", .invocation = "color.channel(\"red\", \"red\")" },
        .{ .name = "list-color", .invocation = "color.channel((red, blue), \"red\")" },
        .{ .name = "map-color", .invocation = "color.channel((tone: red), \"red\")" },
        .{ .name = "deferred-color", .invocation = "color.channel(var(--color), \"red\")" },
        .{ .name = "null-channel", .invocation = "color.channel(red, null)" },
        .{ .name = "boolean-channel", .invocation = "color.channel(red, true)" },
        .{ .name = "number-channel", .invocation = "color.channel(red, 1)" },
        .{ .name = "unquoted-channel", .invocation = "color.channel(red, red)" },
        .{ .name = "uppercase-channel", .invocation = "color.channel(red, \"RED\")" },
        .{ .name = "wrong-stored-channel", .invocation = "color.channel(hsl(1 2% 3%), \"red\")" },
        .{ .name = "wrong-target-channel", .invocation = "color.channel(red, \"x\", rgb)" },
        .{ .name = "boolean-space", .invocation = "color.channel(red, \"red\", true)" },
        .{ .name = "number-space", .invocation = "color.channel(red, \"red\", 1)" },
        .{ .name = "quoted-space", .invocation = "color.channel(red, \"red\", \"rgb\")" },
        .{ .name = "color-space", .invocation = "color.channel(red, \"red\", blue)" },
        .{ .name = "list-space", .invocation = "color.channel(red, \"red\", (rgb, hsl))" },
        .{ .name = "map-space", .invocation = "color.channel(red, \"red\", (space: rgb))" },
        .{ .name = "deferred-space", .invocation = "color.channel(red, \"red\", var(--space))" },
        .{ .name = "unknown-space", .invocation = "color.channel(red, \"red\", custom)" },
        .{ .name = "underscore-space", .invocation = "color.channel(red, \"red\", display_p3)" },
        .{
            .name = "missing-selected",
            .invocation = "color.channel(color(display-p3 none .2 .3), \"red\")",
        },
        .{
            .name = "missing-other",
            .invocation = "color.channel(color(display-p3 none .2 .3), \"green\")",
        },
        .{
            .name = "missing-cross-space",
            .invocation = "color.channel(color(display-p3 none .2 .3), \"green\", srgb)",
        },
        .{
            .name = "missing-alpha",
            .invocation = "color.channel(rgb(1 2 3 / none), \"alpha\")",
        },
    };
    for (invalid) |case| {
        const case_source = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:color\"; @use \"sass:meta\"; $channel: meta.get-function(\"channel\", $module: \"color\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(case_source);
        const name = try std.fmt.allocPrint(
            std.testing.allocator,
            "meta-call-color-channel-{s}.scss",
            .{case.name},
        );
        defer std.testing.allocator.free(name);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, name, case_source, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-channel-global-reference.scss",
            "@use \"sass:meta\"; $channel: meta.get-function(\"channel\"); .a { value: meta.call($channel, red, \"red\"); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-channel-module-not-loaded.scss",
            "@use \"sass:meta\"; $channel: meta.get-function(\"channel\", $module: \"color\"); .a { value: meta.call($channel, red, \"red\"); }",
            .scss,
            .{},
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 3;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-channel-argument-limit.scss",
            "@use \"sass:color\"; @use \"sass:meta\"; $channel: meta.get-function(\"channel\", $module: \"color\"); .a { value: meta.call($channel, red, \"red\", rgb); }",
            .scss,
            argument_limits,
        ),
    );

    var temporary_limits = sass_evaluator.Limits{};
    temporary_limits.max_temporary_bytes = 2;
    try std.testing.expectError(
        error.TemporaryLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-channel-temporary-limit.scss",
            "@use \"sass:color\"; .a { value: color.channel(red, \"red\"); }",
            .scss,
            temporary_limits,
        ),
    );
}

test "native Sass color same function compares direct and reflected colors" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:color";
        \\@use "sass:color" as palette;
        \\@use "sass:color" as *;
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$module: meta.get-function("same", $module: "color");
        \\$alias: meta.get-function("same", $module: "palette");
        \\$star: meta.get-function("same");
        \\$list-args: (red, color.to-space(red, lab));
        \\$map-args: (color2: color.to-space(red, oklab), color1: red);
        \\.values {
        \\  exists: meta.function-exists("same", "color");
        \\  alias-exists: meta.function-exists("same", "palette");
        \\  global-exists: meta.function-exists("same");
        \\  type: meta.type-of($module);
        \\  same-ref: $module == $alias;
        \\  star-ref: $module == $star;
        \\  exact: color.same(red, red);
        \\  legacy-name: color.same(red, #f00);
        \\  legacy-hsl: color.same(hsl(0 100% 50%), red);
        \\  legacy-hwb: color.same(hwb(0 0% 0%), red);
        \\  rgb: color.same(rgb(1 2 3 / .4), rgb(1 2 3 / .4));
        \\  hsl: color.same(hsl(25 20% 30% / .4), hsl(25 20% 30% / .4));
        \\  hwb: color.same(hwb(25 20% 30% / .4), hwb(25 20% 30% / .4));
        \\  lab: color.same(lab(25% 20 30 / .4), lab(25% 20 30 / .4));
        \\  lch: color.same(lch(25% 20 30 / .4), lch(25% 20 30 / .4));
        \\  oklab: color.same(oklab(.25 .2 .3 / .4), oklab(.25 .2 .3 / .4));
        \\  oklch: color.same(oklch(.25 .2 30 / .4), oklch(.25 .2 30 / .4));
        \\  srgb: color.same(color(srgb .1 .2 .3 / .4), color(srgb .1 .2 .3 / .4));
        \\  linear: color.same(color(srgb-linear .1 .2 .3 / .4), color(srgb-linear .1 .2 .3 / .4));
        \\  p3: color.same(color(display-p3 .1 .2 .3 / .4), color(display-p3 .1 .2 .3 / .4));
        \\  a98: color.same(color(a98-rgb .1 .2 .3 / .4), color(a98-rgb .1 .2 .3 / .4));
        \\  prophoto: color.same(color(prophoto-rgb .1 .2 .3 / .4), color(prophoto-rgb .1 .2 .3 / .4));
        \\  rec2020: color.same(color(rec2020 .1 .2 .3 / .4), color(rec2020 .1 .2 .3 / .4));
        \\  d50: color.same(color(xyz-d50 .1 .2 .3 / .4), color(xyz-d50 .1 .2 .3 / .4));
        \\  xyz: color.same(color(xyz .1 .2 .3 / .4), color(xyz .1 .2 .3 / .4));
        \\  different: color.same(red, blue);
        \\  fuzzy-in: color.same(color(srgb .1 .2 .3), color(srgb .100000000004 .2 .3));
        \\  fuzzy-out: color.same(color(srgb .1 .2 .3), color(srgb .100000000005 .2 .3));
        \\  missing-same: color.same(color(display-p3 none .2 .3 / none), color(display-p3 0 .2 .3 / 0));
        \\  missing-different: color.same(color(display-p3 none .2 .3), color(display-p3 .1 .2 .3));
        \\  missing-cross: color.same(color(display-p3 none .2 .3 / none), color.to-space(color(display-p3 0 .2 .3 / 0), xyz));
        \\  powerless-hsl: color.same(hsl(0 0% 50%), hsl(120 0% 50%));
        \\  powerless-lch: color.same(lch(50% 0 0), lch(50% 0 120));
        \\  xyz-alias: color.same(color(xyz .1 .2 .3), color(xyz-d65 .1 .2 .3));
        \\  direct-alias: palette.same(red, color.to-space(red, display-p3));
        \\  star: same(red, color.to-space(red, rec2020));
        \\  reflected: meta.call($module, red, color.to-space(red, lab));
        \\  named: meta.call($module, $color2: color.to-space(red, lch), $color1: red);
        \\  list-splat: meta.call($module, $list-args...);
        \\  map-splat: meta.call($module, $map-args...);
        \\  ordered: meta.call(mark(1, $module), mark(2, red), mark(3, color.to-space(red, xyz)));
        \\  trace: $trace;
        \\  result-type: meta.type-of(meta.call($module, red, red));
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-color-same-function.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{exists:true;alias-exists:true;global-exists:true;type:function;same-ref:true;star-ref:true;exact:true;legacy-name:true;legacy-hsl:true;legacy-hwb:true;rgb:true;hsl:true;hwb:true;lab:true;lch:true;oklab:true;oklch:true;srgb:true;linear:true;p3:true;a98:true;prophoto:true;rec2020:true;d50:true;xyz:true;different:false;fuzzy-in:true;fuzzy-out:false;missing-same:true;missing-different:false;missing-cross:true;powerless-hsl:false;powerless-lch:false;xyz-alias:true;direct-alias:true;star:true;reflected:true;named:true;list-splat:true;map-splat:true;ordered:true;trace:123;result-type:bool}",
        result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);

    const plain_css =
        \\@use "sass:meta";
        \\.plain {
        \\  exists: meta.function-exists("same");
        \\  value: same(red, red);
        \\}
    ;
    var plain_result = try compile(
        std.testing.allocator,
        "color-same-plain-css.scss",
        plain_css,
        .scss,
        .{},
    );
    defer plain_result.deinit();
    try std.testing.expectEqualStrings(
        ".plain{exists:false;value:same(red, red)}",
        plain_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), plain_result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:color" as palette
        \\$reference: m.get-function("same", $module: "palette")
        \\.sass
        \\  exists: m.function-exists("same", "palette")
        \\  global-exists: m.function-exists("same")
        \\  type: m.type-of($reference)
        \\  exact: m.call($reference, red, red)
        \\  cross: palette.same(red, palette.to-space(red, oklab))
        \\  different: palette.same(red, blue)
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-call-color-same-function.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{exists:true;global-exists:false;type:function;exact:true;cross:true;different:false}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseColorSameFunctionAllocationFailures,
        .{},
    );
}

fn exerciseColorSameFunctionAllocationFailures(allocator: std.mem.Allocator) !void {
