test "native Sass color is-powerless function rejects invalid invocations" {
    const invalid = [_]struct {
        name: []const u8,
        invocation: []const u8,
    }{
        .{ .name = "missing", .invocation = "color.is-powerless()" },
        .{ .name = "missing-channel", .invocation = "color.is-powerless(red)" },
        .{ .name = "extra", .invocation = "meta.call($is-powerless, red, \"red\", extra)" },
        .{ .name = "unknown", .invocation = "color.is-powerless($other: red, $channel: \"red\")" },
        .{ .name = "duplicate", .invocation = "meta.call($is-powerless, red, \"red\", $color: blue)" },
        .{ .name = "null-color", .invocation = "color.is-powerless(null, \"red\")" },
        .{ .name = "boolean-color", .invocation = "color.is-powerless(true, \"red\")" },
        .{ .name = "number-color", .invocation = "color.is-powerless(1, \"red\")" },
        .{ .name = "string-color", .invocation = "color.is-powerless(\"red\", \"red\")" },
        .{ .name = "list-color", .invocation = "color.is-powerless((red, blue), \"red\")" },
        .{ .name = "map-color", .invocation = "color.is-powerless((tone: red), \"red\")" },
        .{ .name = "deferred-color", .invocation = "color.is-powerless(var(--color), \"red\")" },
        .{ .name = "null-channel", .invocation = "color.is-powerless(red, null)" },
        .{ .name = "unquoted-channel", .invocation = "color.is-powerless(red, red)" },
        .{ .name = "number-channel", .invocation = "color.is-powerless(red, 1)" },
        .{ .name = "list-channel", .invocation = "color.is-powerless(red, (\"red\", \"green\"))" },
        .{ .name = "map-channel", .invocation = "color.is-powerless(red, (channel: \"red\"))" },
        .{ .name = "deferred-channel", .invocation = "color.is-powerless(red, var(--channel))" },
        .{ .name = "case-sensitive", .invocation = "color.is-powerless(hsl(10 0% 50%), \"HUE\")" },
        .{ .name = "wrong-space-channel", .invocation = "color.is-powerless(lab(50% 0 0), \"hue\")" },
        .{ .name = "legacy-missing-hsl", .invocation = "color.is-powerless(hsl(none none none), \"hue\")" },
        .{ .name = "legacy-missing-hwb", .invocation = "color.is-powerless(hwb(none none 100%), \"hue\")" },
    };
    for (invalid) |case| {
        const case_source = try std.fmt.allocPrint(
            std.testing.allocator,
            "@use \"sass:color\"; @use \"sass:meta\"; $is-powerless: meta.get-function(\"is-powerless\", $module: \"color\"); .a {{ value: {s}; }}",
            .{case.invocation},
        );
        defer std.testing.allocator.free(case_source);
        const name = try std.fmt.allocPrint(
            std.testing.allocator,
            "meta-call-color-is-powerless-{s}.scss",
            .{case.name},
        );
        defer std.testing.allocator.free(name);
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, name, case_source, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-is-powerless-global-reference.scss",
            "@use \"sass:meta\"; $is-powerless: meta.get-function(\"is-powerless\"); .a { value: meta.call($is-powerless, red, \"red\"); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidExpression,
        compile(
            std.testing.allocator,
            "meta-call-color-is-powerless-module-not-loaded.scss",
            "@use \"sass:meta\"; $is-powerless: meta.get-function(\"is-powerless\", $module: \"color\"); .a { value: meta.call($is-powerless, red, \"red\"); }",
            .scss,
            .{},
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 2;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-is-powerless-argument-limit.scss",
            "@use \"sass:color\"; @use \"sass:meta\"; $is-powerless: meta.get-function(\"is-powerless\", $module: \"color\"); .a { value: meta.call($is-powerless, red, \"red\"); }",
            .scss,
            argument_limits,
        ),
    );

    var temporary_limits = sass_evaluator.Limits{};
    temporary_limits.max_temporary_bytes = 2;
    try std.testing.expectError(
        error.TemporaryLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-call-color-is-powerless-temporary-limit.scss",
            "@use \"sass:color\"; .a { value: color.is-powerless(hsl(10 0% 50%), \"hue\"); }",
            .scss,
            temporary_limits,
        ),
    );
}

test "native Sass meta module mixin enumeration preserves ownership and source order" {
    const input =
        \\@use "sass:meta";
        \\@use "sass:meta" as reflect;
        \\@use "sass:map";
        \\@use "sass:math" as numbers;
        \\$trace: 0;
        \\@function mark($digit, $value) {
        \\  $trace: $trace * 10 + $digit !global;
        \\  @return $value;
        \\}
        \\$module: meta.get-function("module-mixins", $module: "meta");
        \\$alias: reflect.get-function("module_mixins", $module: "reflect");
        \\$global: meta.get-function("module-mixins");
        \\$direct: meta.module-mixins(mark(1, "meta"));
        \\$named: reflect.module_mixins($module: mark(2, "reflect"));
        \\$list: (mark(3, "meta"),);
        \\$list-result: meta.call($module, $list...);
        \\$map-args: (module: mark(4, "reflect"));
        \\$map-result: meta.call($module, $map-args...);
        \\$reflected: meta.call($module, "meta");
        \\$legacy: meta.call($global, "meta");
        \\$empty: meta.module-mixins("numbers");
        \\.values {
        \\  exists: meta.function-exists("module-mixins", "meta");
        \\  global-exists: meta.function-exists("module-mixins");
        \\  type: meta.type-of($module);
        \\  same: $module == $alias;
        \\  global-same: $module == $global;
        \\  plain: meta.inspect($direct);
        \\  named: meta.inspect($named);
        \\  list-splat: meta.inspect($list-result);
        \\  map-splat: meta.inspect($map-result);
        \\  reflected: meta.inspect($reflected);
        \\  load: map.get($direct, "load-css") == meta.get-mixin("load-css", "meta");
        \\  apply: map.get($direct, "apply") == meta.get-mixin("apply", "reflect");
        \\  empty: meta.inspect($empty);
        \\  trace: $trace;
        \\  legacy: meta.inspect($legacy);
        \\}
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-module-mixins.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(
        ".values{exists:true;global-exists:true;type:function;same:true;global-same:false;plain:(\"load-css\": get-mixin(\"load-css\"), \"apply\": get-mixin(\"apply\"));named:(\"load-css\": get-mixin(\"load-css\"), \"apply\": get-mixin(\"apply\"));list-splat:(\"load-css\": get-mixin(\"load-css\"), \"apply\": get-mixin(\"apply\"));map-splat:(\"load-css\": get-mixin(\"load-css\"), \"apply\": get-mixin(\"apply\"));reflected:(\"load-css\": get-mixin(\"load-css\"), \"apply\": get-mixin(\"apply\"));load:true;apply:true;empty:();trace:1234;legacy:(\"load-css\": get-mixin(\"load-css\"), \"apply\": get-mixin(\"apply\"))}",
        result.css(),
    );
    const diagnostics = result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 1), diagnostics.len);
    try std.testing.expectEqual(
        preprocessor.diagnostics.Severity.warning,
        diagnostics[0].severity,
    );
    try std.testing.expectEqual(
        preprocessor.diagnostics.Code.invalid_operation,
        diagnostics[0].code,
    );
    try std.testing.expectEqualStrings(
        "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        diagnostics[0].message,
    );

    const star =
        \\@use "sass:meta" as *;
        \\@use "sass:meta" as reflect;
        \\$mixins: module-mixins("reflect");
        \\.star {
        \\  type: type-of($mixins);
        \\  same: $mixins == module_mixins("reflect");
        \\  plain: inspect($mixins);
        \\}
    ;
    var star_result = try compile(
        std.testing.allocator,
        "meta-module-mixins-star.scss",
        star,
        .scss,
        .{},
    );
    defer star_result.deinit();
    try std.testing.expectEqualStrings(
        ".star{type:map;same:true;plain:(\"load-css\": get-mixin(\"load-css\"), \"apply\": get-mixin(\"apply\"))}",
        star_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), star_result.nativeDiagnostics().len);

    const indented =
        \\@use "sass:meta" as m
        \\@use "sass:meta" as reflect
        \\$reference: m.get-function("module-mixins", $module: "reflect")
        \\$mixins: m.call($reference, $module: "m")
        \\.sass
        \\  type: m.type-of($mixins)
        \\  plain: m.inspect($mixins)
        \\  load: m.accepts-content(m.get-mixin("load-css", "m"))
        \\  apply: m.accepts-content(m.get-mixin("apply", "reflect"))
    ;
    var sass_result = try compile(
        std.testing.allocator,
        "meta-module-mixins.sass",
        indented,
        .sass,
        .{},
    );
    defer sass_result.deinit();
    try std.testing.expectEqualStrings(
        ".sass{type:map;plain:(\"load-css\": get-mixin(\"load-css\"), \"apply\": get-mixin(\"apply\"));load:false;apply:true}",
        sass_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);

    var legacy_result = try compile(
        std.testing.allocator,
        "meta-module-mixins-global.scss",
        "@use \"sass:meta\"; $mixins: module-mixins(\"meta\"); .global { value: meta.inspect($mixins); }",
        .scss,
        .{},
    );
    defer legacy_result.deinit();
    try std.testing.expectEqualStrings(
        ".global{value:(\"load-css\": get-mixin(\"load-css\"), \"apply\": get-mixin(\"apply\"))}",
        legacy_result.css(),
    );
    try std.testing.expectEqual(@as(usize, 1), legacy_result.nativeDiagnostics().len);
    try std.testing.expectEqualStrings(
        "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        legacy_result.nativeDiagnostics()[0].message,
    );

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseMetaModuleMixinsAllocationFailures,
        .{},
    );
}

