    );
    try std.testing.expectEqual(@as(usize, 0), sass_result.nativeDiagnostics().len);

    var backing = DeterministicAllocationBacking{ .child = std.testing.allocator };
    try std.testing.checkAllAllocationFailures(
        backing.allocator(),
        exerciseReflectedMetaApplyInvocationAllocationFailures,
        .{},
    );
}

fn exerciseReflectedMetaApplyInvocationAllocationFailures(
    allocator: std.mem.Allocator,
) !void {
    const input =
        \\@use "sass:meta";
        \\@mixin paint($value) { value: $value; }
        \\$apply: meta.get-mixin("apply", $module: "meta");
        \\$paint: meta.get-mixin("paint");
        \\.allocation { @include meta.apply($apply, $paint, ok); }
    ;
    var result = try compile(
        allocator,
        "meta-apply-reflected-apply-allocation.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(".allocation{value:ok}", result.css());
    try std.testing.expectEqual(@as(usize, 0), result.nativeDiagnostics().len);
}

test "native Sass meta apply rejects invalid reflected apply invocation" {
    const invalid = [_]struct {
        name: []const u8,
        input: []const u8,
    }{
        .{
            .name = "meta-apply-reflected-apply-missing-target.scss",
            .input = "@use \"sass:meta\"; $apply: meta.get-mixin(\"apply\", $module: \"meta\"); .a { @include meta.apply($apply); }",
        },
        .{
            .name = "meta-apply-reflected-apply-nested-missing-target.scss",
            .input = "@use \"sass:meta\"; $apply: meta.get-mixin(\"apply\", $module: \"meta\"); .a { @include meta.apply($apply, $apply); }",
        },
        .{
            .name = "meta-apply-reflected-apply-non-callable.scss",
            .input = "@use \"sass:meta\"; $apply: meta.get-mixin(\"apply\", $module: \"meta\"); .a { @include meta.apply($apply, 1); }",
        },
        .{
            .name = "meta-apply-reflected-apply-function.scss",
            .input = "@use \"sass:meta\"; @function fn($value) { @return $value; } $apply: meta.get-mixin(\"apply\", $module: \"meta\"); .a { @include meta.apply($apply, meta.get-function(\"fn\"), ok); }",
        },
    };
    for (invalid) |case| {
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, case.input, .scss, .{}),
        );
    }

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 2;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-apply-reflected-apply-argument-limit.scss",
            "@use \"sass:meta\"; @mixin plain {} $apply: meta.get-mixin(\"apply\", $module: \"meta\"); .a { @include meta.apply($apply, $apply, meta.get-mixin(\"plain\")); }",
            .scss,
            argument_limits,
        ),
    );
}

test "native Sass meta apply rejects unavailable or invalid mixin application" {
    const invalid = [_]struct {
        name: []const u8,
        input: []const u8,
    }{
        .{
            .name = "meta-apply-missing-reference.scss",
            .input = "@use \"sass:meta\"; .a { @include meta.apply(); }",
        },
        .{
            .name = "meta-apply-non-callable.scss",
            .input = "@use \"sass:meta\"; .a { @include meta.apply(1); }",
        },
        .{
            .name = "meta-apply-function-reference.scss",
            .input = "@use \"sass:meta\"; @function fn($value) { @return $value; } .a { @include meta.apply(meta.get-function(\"fn\"), ok); }",
        },
        .{
            .name = "meta-apply-duplicate-reference.scss",
            .input = "@use \"sass:meta\"; @mixin plain($value) { value: $value; } $reference: meta.get-mixin(\"plain\"); .a { @include meta.apply($reference, $mixin: $reference, $value: ok); }",
        },
        .{
            .name = "meta-apply-missing-target-argument.scss",
            .input = "@use \"sass:meta\"; @mixin plain($value) { value: $value; } .a { @include meta.apply(meta.get-mixin(\"plain\")); }",
        },
        .{
            .name = "meta-apply-extra-target-argument.scss",
            .input = "@use \"sass:meta\"; @mixin plain($value) { value: $value; } .a { @include meta.apply(meta.get-mixin(\"plain\"), ok, extra); }",
        },
        .{
            .name = "meta-apply-unknown-target-argument.scss",
            .input = "@use \"sass:meta\"; @mixin plain($value) { value: $value; } .a { @include meta.apply(meta.get-mixin(\"plain\"), $value: ok, $other: extra); }",
        },
        .{
            .name = "meta-apply-unloaded-namespace.scss",
            .input = "@use \"sass:meta\"; @mixin plain($value) { value: $value; } .a { @include other.apply(meta.get-mixin(\"plain\"), ok); }",
        },
    };
    for (invalid) |case| {
        try std.testing.expectError(
            error.InvalidExpression,
            compile(std.testing.allocator, case.name, case.input, .scss, .{}),
        );
    }

    try std.testing.expectError(
        error.InvalidSassSyntax,
        compile(
            std.testing.allocator,
            "meta-apply-content-rejected.scss",
            "@use \"sass:meta\"; @mixin plain($value) { value: $value; } .a { @include meta.apply(meta.get-mixin(\"plain\"), ok) { nested: yes; } }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.InvalidSassSyntax,
        compile(
            std.testing.allocator,
            "meta-apply-global-unavailable.scss",
            "@use \"sass:meta\"; @mixin plain($value) { value: $value; } .a { @include apply(meta.get-mixin(\"plain\"), ok); }",
            .scss,
            .{},
        ),
    );
    try std.testing.expectError(
        error.UnsupportedFeature,
        compile(
            std.testing.allocator,
            "meta-apply-load-css-target-unavailable.scss",
            "@use \"sass:meta\"; .a { @include meta.apply(meta.get-mixin(\"load-css\", $module: \"meta\"), \"missing\"); }",
            .scss,
            .{},
        ),
    );

    var argument_limits = sass_evaluator.Limits{};
    argument_limits.max_function_arguments = 1;
    try std.testing.expectError(
        error.FunctionArgumentLimitExceeded,
        compile(
            std.testing.allocator,
            "meta-apply-argument-limit.scss",
            "@use \"sass:meta\"; @mixin plain($value) { value: $value; } .a { @include meta.apply(meta.get-mixin(\"plain\"), ok); }",
            .scss,
            argument_limits,
        ),
    );
}

test "native Sass meta call preserves the legacy warning" {
    const input =
        \\@use "sass:meta";
        \\@function identity($value) { @return $value; }
        \\.legacy { value: call(meta.get-function("identity"), ok); }
    ;
    var result = try compile(
        std.testing.allocator,
        "meta-call-global.scss",
        input,
        .scss,
        .{},
    );
    defer result.deinit();
    try std.testing.expectEqualStrings(".legacy{value:ok}", result.css());
    const diagnostics = result.nativeDiagnostics();
    try std.testing.expectEqual(@as(usize, 1), diagnostics.len);
    try std.testing.expectEqual(
        preprocessor.diagnostics.Severity.warning,
        diagnostics[0].severity,
    );
    try std.testing.expectEqual(
        preprocessor.diagnostics.Code.invalid_operation,
        diagnostics[0].code,
    );
    try std.testing.expectEqualStrings(
        "Global built-in functions are deprecated and will be removed in Dart Sass 3.0.0.",
        diagnostics[0].message,
    );
}

