        \\  from-list: selector.is-superselector((".a", ".b"), (".a.x", ".b.y"));
        \\  alias: sel.is-superselector("#id", "#id.item");
        \\  star: is-superselector("[x=y]", "button[x=y]");
        \\  keyword: selector.is-superselector($sub: ".k.x", $super: ".k");
