        \\  same-component: selector.extend(".a:is(.a,.b)", ".a", ".x");
        \\  functional-extender: selector.extend(":is(.a,.b)", ".a", ":is(.x,.y)");
        \\  ignored-extender: selector.replace(":is(.a,.b)", ".a", ":where(.x,.y)");
        \\  case-distinct: selector.extend(":IS(.a,.b)", ".a", ".x");
