            .input = "@use \"sass:string\"; .a { value: string.nope($undefined); }",
            .expected = error.InvalidExpression,
        },
        .{
            .name = "case-sensitive-string-namespace.scss",
            .input = "@use \"sass:string\" as String; .a { value: string.length(abc); }",
            .expected = error.InvalidExpression,
